/* Isogeny Evidence Lab — single-page frontend (vanilla JS, hash routing, dark mode). */
const $ = (s, r = document) => r.querySelector(s);
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const fmt = (v) => v === null || v === undefined ? '<span class="na">—</span>' : typeof v === "number" ? (Number.isInteger(v) ? String(v) : v.toPrecision(4)) : esc(v);
const badge = (s) => s ? `<span class="badge b-${esc(s)}">${esc(String(s).replace(/_/g, " "))}</span>` : "";
const st = (s) => `<span class="st ${esc(s)}">${esc(String(s || "not_tested").replace(/_/g, " "))}</span>`;
const prov = (p) => `<span class="prov ${esc(p)}">${esc(p)}</span>`;
const demo = (x) => x ? badge("demo") : "";
const passmark = (p) => p === true ? '<span class="ok">pass</span>' : p === false ? '<span class="bad">FAIL</span>' : '<span class="na">n/a</span>';
const when = (s) => s ? new Date(s).toLocaleString() : "—";
const nl = (arr) => (arr && arr.length) ? `<ul class="tight">${arr.map(x => `<li>${esc(typeof x === "string" ? x : JSON.stringify(x))}</li>`).join("")}</ul>` : '<span class="na">none</span>';
const json = (o) => `<pre>${esc(JSON.stringify(o, null, 1))}</pre>`;
const short = (s, n = 12) => s ? `<code>${esc(String(s).slice(0, n))}…</code>` : '<span class="na">—</span>';
const labels = (ls) => (ls || []).map(l => `<span class="badge b-${esc(l.label || l)}" title="${esc(l.claim || "")}">${esc(String(l.label || l).replace(/_/g, " "))}</span>`).join(" ") || '<span class="na">none</span>';
let TOKEN = localStorage.getItem("iel_token"), ME = null;

// ---- event handlers: registered per render, dispatched by delegation (no inline handlers)
let HANDLERS = [];
const on = (kind, fn) => `data-h-${kind}="${HANDLERS.push(fn) - 1}"`;
for (const kind of ["click", "submit", "change"]) document.addEventListener(kind, (e) => {
  let el = e.target.closest ? e.target.closest(`[data-h-${kind}]`) : null;
  while (el) { const fn = HANDLERS[+el.getAttribute(`data-h-${kind}`)]; if (fn) { const r = fn.call(el, e); if (kind === "submit" || r === false) e.preventDefault(); } el = el.parentElement ? el.parentElement.closest(`[data-h-${kind}]`) : null; }
});

function staticApi(path, opts) {
  const S = window.IEL_STATIC, m = opts.method || "GET";
  if (m !== "GET") { const v = S.get[m + " " + path]; if (v) return Promise.resolve(JSON.parse(JSON.stringify(v)));
    throw new Error("Read-only static demo: changes are disabled here. Run the app locally (see README) to import, run tests, approve or export."); }
  const v = S.get[path]; if (v === undefined) return Promise.reject(new Error("Not part of the static snapshot: " + path));
  return Promise.resolve(JSON.parse(JSON.stringify(v)));
}
async function api(path, opts = {}) {
  if (window.IEL_STATIC) return staticApi(path, opts);
  const headers = {"Content-Type": "application/json", ...(TOKEN ? {Authorization: "Bearer " + TOKEN} : {})};
  if (opts.body && typeof opts.body !== "string" && !(opts.body instanceof FormData)) opts.body = JSON.stringify(opts.body);
  if (opts.body instanceof FormData) delete headers["Content-Type"];
  const r = await fetch(path, {...opts, headers});
  if (r.status === 401) { TOKEN = null; localStorage.removeItem("iel_token"); render(); throw new Error("not signed in"); }
  if (!r.ok) { let m = r.statusText; try { m = (await r.json()).detail || m; } catch {} throw new Error(typeof m === "string" ? m : JSON.stringify(m)); }
  const ct = r.headers.get("content-type") || "";
  return ct.includes("json") ? r.json() : r;
}
function toast(msg, bad = false) { const d = document.createElement("div"); const ro = /^Read-only static demo/.test(msg); d.className = "callout toast " + (bad ? "bad" : "info") + (ro ? " ro" : ""); d.setAttribute("role", "status"); d.textContent = msg; document.body.appendChild(d); setTimeout(() => d.remove(), ro ? 8000 : 5500); }
async function act(fn, ok = "Done") { try { await fn(); toast(ok); render(); } catch (e) { toast(e.message, true); } }
window.dl = (url, name) => { const fd = window.IEL_STATIC && window.IEL_STATIC.filedata[url]; if (fd) { const bytes = Uint8Array.from(atob(fd.b64), c => c.charCodeAt(0)); const a = document.createElement("a"); a.href = URL.createObjectURL(new Blob([bytes])); a.download = fd.name || name; a.click(); toast("Downloaded " + (fd.name || name)); return false; }
  if (window.IEL_STATIC) { toast("Not part of the static snapshot", true); return false; }
  fetch(url, {headers: {Authorization: "Bearer " + TOKEN}}).then(async r => { if (!r.ok) throw new Error(await r.text()); const b = await r.blob(); const a = document.createElement("a"); a.href = URL.createObjectURL(b); a.download = (r.headers.get("content-disposition") || "").match(/filename="([^"]+)"/)?.[1] || name; a.click(); toast("Downloaded " + a.download + (r.headers.get("X-SHA256") ? " · SHA-256 " + r.headers.get("X-SHA256").slice(0, 16) + "…" : "")); }).catch(err => toast(err.message, true)); return false; };
const dlBtn = (url, name, label, cls = "ghost sm") => `<button class="${cls}" ${on("click", () => dl(url, name))}>${esc(label)}</button>`;
const readJsonFile = (input) => new Promise((res, rej) => { const f = input.files[0]; if (!f) return rej(new Error("choose a file")); const r = new FileReader(); r.onload = () => { try { res(JSON.parse(r.result)); } catch (e) { rej(new Error("file is not JSON")); } }; r.readAsText(f); });
const readB64File = (input) => new Promise((res, rej) => { const f = input.files[0]; if (!f) return res(null); const r = new FileReader(); r.onload = () => res({name: f.name, b64: r.result.split(",")[1]}); r.onerror = rej; r.readAsDataURL(f); });

// ---- router
const routes = [];
const route = (re, fn) => routes.push([re, fn]);
async function render() {
  HANDLERS = [];
  const app = $("#app");
  if (window.IEL_STATIC && !TOKEN) TOKEN = "static-demo";
  if (!TOKEN) { $("#projnav").innerHTML = ""; $("#whoami").textContent = ""; app.innerHTML = landingView(); return; }
  if (!ME) { try { ME = await api("/api/auth/me"); } catch { return; } }
  $("#whoami").textContent = `${ME.name}${ME.is_admin ? " (admin)" : ""}`;
  const hash = location.hash.replace(/^#/, "") || "/";
  const [path, qs] = hash.split("?");
  const q = Object.fromEntries(new URLSearchParams(qs || ""));
  for (const [re, fn] of routes) { const m = path.match(re); if (m) { app.innerHTML = '<p class="muted">Loading…</p>'; try { app.innerHTML = await fn(...m.slice(1), q); if (window.IEL_STATIC) app.querySelectorAll("form").forEach(f => f.noValidate = true); } catch (e) { app.innerHTML = `<div class="callout bad">${esc(e.message)}</div>`; } window.scrollTo(0, 0); return; } }
  app.innerHTML = "<p>Not found.</p>";
}
window.addEventListener("hashchange", render);
$("#logout").onclick = async () => { if (window.IEL_STATIC) return toast("Static demo: signed in as the seeded demo engineer (read-only)."); try { await api("/api/auth/logout", {method: "POST"}); } catch {} TOKEN = null; ME = null; localStorage.removeItem("iel_token"); location.hash = "#/"; render(); };

function landingView() {
  const A = window.IEL_ASSETS;
  setTimeout(() => { const f = $("#loginform"); if (f) f.onsubmit = async (e) => { e.preventDefault(); try { const r = await api("/api/auth/login", {method: "POST", body: {email: $("#email").value, password: $("#password").value}}); TOKEN = r.token; localStorage.setItem("iel_token", TOKEN); ME = r.user; location.hash = $("#loginform").dataset.next || "#/"; render(); } catch (err) { $("#loginerr").textContent = err.message; } }; });
  return `<section class="hero"><div><img src="${esc(A.logoDark)}" alt="${esc(A.logoAlt)}"><div class="product" style="margin:14px 0 0;border:0;padding:0">Evidence Lab</div>
  <h1>Test your cryptographic implementation. Understand the evidence. Improve with confidence.</h1>
  <p>Import your current implementation, run reproducible tests, investigate findings and compare improvements across versions.</p>
  <div class="ctas"><button ${on("click", () => { $("#loginform").dataset.next = "#/new"; $("#email").focus(); })}>Import implementation</button><button class="ivory" ${on("click", () => { $("#loginform").dataset.next = "#/sample"; $("#email").focus(); })}>Explore sample project</button></div></div>
  <div class="panel login"><h2 style="margin-top:0">Sign in</h2><form id="loginform"><label for="email">Email</label><input id="email" value="engineer@customer.local" autocomplete="username"><label for="password">Password</label><input id="password" type="password" value="engineer-demo-password" autocomplete="current-password">
  <p class="err" id="loginerr" aria-live="polite"></p><button>Sign in</button></form>
  <p class="muted small" style="margin-top:14px">Demo accounts (seeded): engineer@customer.local (editor) · reviewer@isogeny.local (reviewer) · admin@isogeny.local (admin). Passwords: <code>&lt;role&gt;-demo-password</code>. Sample data is illustrative.</p></div></section>`;
}
function projNav(pid, cur) {
  const items = [["", "Overview"], ["/implementations", "Implementations"], ["/tests", "Tests & Benchmarks"], ["/research", "Research & Experiments"], ["/findings", "Findings & Recommendations"], ["/evidence", "Evidence"]];
  $("#projnav").innerHTML = items.map(([p, l]) => `<a href="#/p/${pid}${p}" class="${cur === p ? "active" : ""}">${l}</a>`).join("");
}
const tabs = (base, cur, items) => `<div class="tabs">${items.map(([k, l]) => `<a href="${base}${k ? "?tab=" + k : ""}" class="${cur === k ? "active" : ""}">${esc(l)}</a>`).join("")}</div>`;

// ---- projects list / new / sample
route(/^\/$/, async () => {
  $("#projnav").innerHTML = "";
  const ps = await api("/api/projects");
  return `<div class="row"><div><h1>Projects</h1><p class="sub">Each project assesses one implementation lineage. Counts are from append-only run records; there is no overall score.</p></div>
  <span class="right"></span><a href="#/new"><button>Import implementation</button></a> ${ps.find(p => p.is_demo) ? `<a href="#/p/${ps.find(p => p.is_demo).id}"><button class="ivory">Explore sample project</button></a>` : ""}</div>
  <div class="panel"><table><tr><th>Project</th><th>Current implementation</th><th class="num">Runs</th><th class="num">Failed (latest)</th><th class="num">Open findings</th><th class="num">Proposals awaiting approval</th><th class="num">Recommendations awaiting implementation</th></tr>
  ${ps.map(p => `<tr class="clickable" tabindex="0" ${on("click", () => location.hash = `#/p/${p.id}`)}><td><b>${esc(p.name)}</b> ${demo(p.is_demo)}<br><span class="muted small">${esc(p.description)}</span></td><td>${esc(p.current_implementation || "—")}</td><td class="num">${p.counts.runs}</td><td class="num ${p.counts.failed ? "bad" : ""}">${p.counts.failed}</td><td class="num ${p.counts.open_findings ? "warn" : ""}">${p.counts.open_findings}</td><td class="num">${p.counts.proposals_awaiting}</td><td class="num">${p.counts.recommendations_awaiting_implementation}</td></tr>`).join("") || '<tr><td colspan=7 class="muted">No projects yet.</td></tr>'}</table></div>`;
});
route(/^\/sample$/, async () => { const ps = await api("/api/projects"); const s = ps.find(p => p.is_demo) || ps[0]; location.hash = s ? `#/p/${s.id}` : "#/"; return ""; });
route(/^\/new$/, async () => {
  $("#projnav").innerHTML = "";
  return `<h1>New project</h1><p class="sub">Create the project, then import the first implementation version. Supported workflow: digital-signature library (IoT and application-layer adapters are future placeholders).</p>
  <div class="panel"><form ${on("submit", async (e) => { const b = Object.fromEntries(new FormData(e.target).entries()); try { b.runtime_environment = JSON.parse(b.runtime_environment || "{}"); } catch { return toast("runtime environment must be JSON", true); } act(async () => { const p = await api("/api/projects", {method: "POST", body: b}); location.hash = `#/p/${p.id}/implementations?import=1`; }, "Project created"); })}>
  <div class="grid g2"><div><label>Name</label><input name="name" required></div><div><label>Description</label><input name="description"></div><div><label>Intended use</label><input name="intended_use" placeholder="what the implementation signs/verifies and for whom"></div><div><label>Threat assumptions</label><input name="threat_assumptions" placeholder="who the attacker is and what they can do"></div></div>
  <label>Runtime environment (JSON: deployment, hardware)</label><input name="runtime_environment" value='{"deployment": "", "hardware": ""}'><p><button>Create project</button></p></form></div>`;
});

// ---- overview
route(/^\/p\/([^/]+)$/, async (pid) => {
  projNav(pid, "");
  const o = await api(`/api/projects/${pid}/overview`);
  const p = o.project, cur = o.current_implementation;
  const cov = o.coverage;
  const testIds = cov.length ? Object.keys(cov[0].tests) : [];
  return `<h1>${esc(p.name)} ${demo(p.is_demo)}</h1><p class="sub">${esc(p.description)} · intended use: ${esc(p.intended_use || "—")}</p>
  ${cur && cur.seeded_defect ? `<div class="callout demo"><b>Seeded defect (demonstration):</b> ${esc(cur.seeded_defect)}</div>` : ""}
  <div class="grid g3">
  <div class="panel"><h3>What implementation are we assessing?</h3>${cur ? `<div class="stat">${esc(cur.name)} ${esc(cur.version)}<small>${esc(cur.algorithm)} · ${esc(cur.library)} ${esc(cur.library_version)} · ${badge(cur.status)}</small></div><p class="small muted">source digest ${short(cur.source_digest)} · imported ${when(cur.imported_at)} · adapter ${esc(cur.adapter_kind)} · compatibility ${badge(cur.compatibility?.status)}</p><a href="#/p/${pid}/implementations/${cur.id}">Details</a>` : `<p class="muted">No implementation imported.</p><a href="#/p/${pid}/implementations?import=1"><button>Import implementation</button></a>`}</div>
  <div class="panel"><h3>What failed or remains uncertain?</h3>${o.open_findings.length ? `<ul class="tight">${o.open_findings.map(f => `<li><a href="#/p/${pid}/findings/${f.id}">${esc(f.title)}</a> ${badge(f.status)} ${badge(f.reproduction_status)} ${demo(f.is_demo)}</li>`).join("")}</ul>` : '<p class="muted">No open findings.</p>'}<h3>Untested areas</h3>${nl(o.untested)}</div>
  <div class="panel"><h3>What experiment should we run next?</h3>${o.next_experiment ? `<p><a href="#/p/${pid}/experiments/${o.next_experiment.id}">${esc(o.next_experiment.title)}</a> ${badge(o.next_experiment.status)} ${o.next_experiment.executable ? "" : '<span class="tag">proposal only</span>'}</p>` : '<p class="muted">No proposal pending. Use “Propose experiments” in Research & Experiments.</p>'}
  <h3>What should engineering consider changing?</h3>${o.recommendations.length ? `<ul class="tight">${o.recommendations.map(r => `<li><a href="#/p/${pid}/recommendations/${r.id}">${esc(r.title)}</a> ${badge(r.guidance_kind)} ${badge(r.status)} ${r.awaiting_external_implementation ? '<span class="tag">awaiting external implementation</span>' : ""}</li>`).join("")}</ul>` : '<p class="muted">No recommendations yet.</p>'}</div></div>
  <div class="panel"><h2>What has actually been tested? — coverage by version</h2><table><tr><th>Implementation</th>${testIds.map(t => `<th>${esc(t)}</th>`).join("")}</tr>
  ${cov.map(c => `<tr><td><a href="#/p/${pid}/implementations/${c.implementation.id}">${esc(c.implementation.label)}</a> ${badge(c.implementation.status)}</td>${testIds.map(t => { const s = c.tests[t]; return `<td>${st(s.status)}${s.run_id ? ` <a class="small" href="#/p/${pid}/runs/${s.run_id}">#${s.sequence}</a> <span class="tag">${esc(s.execution_mode)}</span>` : ""}${s.failing && s.failing.length ? `<br><span class="bad small">${esc(s.failing.join(", "))}</span>` : ""}</td>`; }).join("")}</tr>`).join("") || '<tr><td class="muted">No implementations.</td></tr>'}</table>
  <p class="small muted">${Object.entries(o.status_legend).map(([k, v]) => `<b>${esc(k.replace(/_/g, " "))}</b>: ${esc(v)}`).join(" · ")}</p></div>
  <div class="grid g2"><div class="panel"><h2>Latest benchmark (current version)</h2>${o.latest_benchmark ? `<p class="small muted">run #${o.latest_benchmark.sequence} · ${esc(o.latest_benchmark.execution_mode)} · ${st(o.latest_benchmark.classification)} · <a href="#/p/${pid}/runs/${o.latest_benchmark.run_id}">details</a></p><table>${Object.entries(o.latest_benchmark.metrics).map(([k, v]) => `<tr><td><code>${esc(k)}</code></td><td class="num">${fmt(v)}</td></tr>`).join("")}</table>
  <h3>Requirements</h3><table>${o.latest_benchmark.requirement_results.map(r => `<tr><td>${esc(r.name)}</td><td><code>${esc(r.metric)} ${esc(r.operator)} ${r.threshold} ${esc(r.unit)}</code></td><td class="num">${fmt(r.observed)}</td><td>${passmark(r.pass)} <span class="tag">${esc(r.note || "")}</span></td></tr>`).join("") || '<tr><td class="muted">none</td></tr>'}</table>` : '<p class="muted">No completed run for the current version.</p>'}</div>
  <div class="panel"><h2>Changes since the previous version</h2>${o.changes_since_previous ? `<p>${esc(o.changes_since_previous.previous)} → <b>${esc(o.changes_since_previous.current)}</b></p>${o.changes_since_previous.change_report ? `<div class="callout info"><b>Customer-reported change:</b> ${esc(o.changes_since_previous.change_report)}</div>` : ""}<table>${Object.entries(o.changes_since_previous.manifest_diff).map(([k, d]) => `<tr><td><code>${esc(k)}</code></td><td class="small">${esc(JSON.stringify(d.previous))}</td><td class="small">${esc(JSON.stringify(d.current))}</td></tr>`).join("") || '<tr><td class="muted">manifest unchanged</td></tr>'}</table>
  ${Object.entries(o.changes_since_previous.test_outcomes).map(([t, x]) => `<p><code>${esc(t)}</code>: ${st(x.classification.previous)} → ${st(x.classification.current)}${x.fixed.length ? ` · fixed: <span class="ok">${esc(x.fixed.join(", "))}</span>` : ""}${x.regressed.length ? ` · regressed: <span class="bad">${esc(x.regressed.join(", "))}</span>` : ""}</p>`).join("")}` : '<p class="muted">Only one version imported.</p>'}
  <h3>Proposals awaiting approval</h3>${o.proposals_awaiting_approval.length ? `<ul class="tight">${o.proposals_awaiting_approval.map(x => `<li><a href="#/p/${pid}/experiments/${x.id}">${esc(x.title)}</a>${x.executable ? "" : ' <span class="tag">proposal only</span>'}</li>`).join("")}</ul>` : '<p class="muted">none</p>'}</div></div>`;
});

// ---- implementations
route(/^\/p\/([^/]+)\/implementations$/, async (pid, q) => {
  projNav(pid, "/implementations");
  const [impls, cat, recs] = await Promise.all([api(`/api/projects/${pid}/implementations`), api("/api/catalog"), api(`/api/projects/${pid}/recommendations`)]);
  return `<h1>Implementations</h1><p class="sub">Each import is a version with its manifest, source identity and compatibility. Importing code never executes it; execution happens only in the sandbox after the static check. Never upload production private keys.</p>
  <div class="panel"><table><tr><th>Name / version</th><th>Status</th><th>Algorithm · library</th><th>Source</th><th>Adapter</th><th>Compatibility</th><th class="num">Runs</th><th>Latest</th><th>Imported</th></tr>
  ${impls.map(i => `<tr class="clickable" tabindex="0" ${on("click", () => location.hash = `#/p/${pid}/implementations/${i.id}`)}><td><b>${esc(i.name)} ${esc(i.version)}</b> ${demo(i.is_demo)}${i.seeded_defect ? ' <span class="badge b-demo">seeded defect</span>' : ""}</td><td>${badge(i.status)}</td><td>${esc(i.algorithm)}<br><span class="muted small">${esc(i.library)} ${esc(i.library_version)}</span></td><td class="small"><code>${esc(i.source_revision || "—")}</code><br>${short(i.source_digest)}</td><td>${esc(i.adapter_kind)}</td><td>${badge(i.compatibility?.status || "unchecked")}</td><td class="num">${i.run_count}</td><td>${st(i.latest_classification)}</td><td class="muted small">${when(i.imported_at)}</td></tr>`).join("") || '<tr><td colspan=9 class="muted">No implementations imported.</td></tr>'}</table></div>
  <div class="panel ${q.import ? "elev" : ""}" id="importpanel"><h2>Import implementation version</h2>
  <form ${on("submit", async (e) => { const f = e.target; let manifest; try { manifest = JSON.parse(f.manifest.value); } catch { return toast("manifest must be JSON", true); } for (const k of ["name", "version", "adapter_kind", "profile_id", "parent_id", "recommendation_id", "change_report"]) { const v = f[k] && f[k].value; if (v) manifest[k] = v; } if (!manifest.profile_id) delete manifest.profile_id; if (!manifest.parent_id) delete manifest.parent_id; if (!manifest.recommendation_id) delete manifest.recommendation_id; const snap = await readB64File(f.snapshot).catch(() => null); let existing = null; if (f.existing.files[0]) { existing = await readJsonFile(f.existing).catch(err => { toast(err.message, true); }); } act(async () => { const r = await api(`/api/projects/${pid}/implementations/import`, {method: "POST", body: {manifest, source_snapshot_b64: snap ? snap.b64 : null, source_snapshot_filename: snap ? snap.name : null, existing_results: existing}}); location.hash = `#/p/${pid}/implementations/${r.id}`; }, "Imported"); })}>
  <div class="grid g4"><div><label>Name</label><input name="name" required></div><div><label>Version</label><input name="version" required></div><div><label>Adapter kind</label><select name="adapter_kind"><option value="module">module — customer source snapshot (adapter.py)</option><option value="profile">profile — catalog library profile</option><option value="results_only">results only — no execution</option></select></div><div><label>Catalog profile (profile kind)</label><select name="profile_id"><option value="">—</option>${cat.profiles.filter(x => x.fixture).map(x => `<option value="${x.id}">${esc(x.label)}</option>`).join("")}</select></div></div>
  <label>Manifest (JSON): purpose, algorithm, parameters, library, library_version, dependencies, configuration, runtime_environment, source_revision, build_identity, intended_use, threat_assumptions, notes — see <code>seeds/sample_manifest_v1_0.json</code></label><textarea name="manifest">{"purpose": "signatures", "algorithm": "Ed25519", "parameters": {"signature_bytes": 64}, "library": "", "library_version": "", "dependencies": [], "configuration": {}, "runtime_environment": {"deployment": ""}, "source_revision": "", "build_identity": {}, "intended_use": "", "threat_assumptions": ""}</textarea>
  <div class="grid g2"><div><label>Source snapshot (.py adapter or .zip with adapter.py at root; checked statically, never executed on import; private keys rejected)</label><input type="file" name="snapshot" accept=".py,.zip"></div><div><label>Existing results document (optional JSON in the result schema; imported as unsigned evidence)</label><input type="file" name="existing" accept=".json"></div></div>
  <div class="grid g3"><div><label>Replaces version (parent)</label><select name="parent_id"><option value="">—</option>${impls.map(i => `<option value="${i.id}">${esc(i.name)} ${esc(i.version)}</option>`).join("")}</select></div><div><label>Implements recommendation</label><select name="recommendation_id"><option value="">—</option>${recs.filter(r => r.status === "approved").map(r => `<option value="${r.id}">${esc(r.title)}</option>`).join("")}</select></div><div><label>Customer-reported change (what you changed externally)</label><input name="change_report"></div></div>
  <p><button>Import</button> <span class="muted small">Repository integrations are not implemented; use manual upload or structured entry.</span></p></form></div>`;
});
route(/^\/p\/([^/]+)\/implementations\/([^/]+)$/, async (pid, iid) => {
  projNav(pid, "/implementations");
  const i = await api(`/api/projects/${pid}/implementations/${iid}`);
  let snap = null; if (i.source_snapshot_artifact_id) { try { snap = await api(`/api/projects/${pid}/implementations/${iid}/snapshot`); } catch {} }
  const c = i.compatibility || {};
  return `<h1>${esc(i.name)} ${esc(i.version)} ${badge(i.status)} ${demo(i.is_demo)}</h1><p class="sub">${esc(i.purpose)} · ${esc(i.algorithm)} · ${esc(i.library)} ${esc(i.library_version)} · imported ${when(i.imported_at)}</p>
  ${i.seeded_defect ? `<div class="callout demo"><b>Seeded defect (demonstration):</b> ${esc(i.seeded_defect)}</div>` : ""}
  ${i.change_report ? `<div class="callout info"><b>Customer-reported change:</b> ${esc(i.change_report)}</div>` : ""}
  <div class="grid g2"><div>
  <div class="panel"><h2>Identity</h2><dl class="kv"><dt>Source revision</dt><dd><code>${esc(i.source_revision || "—")}</code></dd><dt>Source digest (SHA-256)</dt><dd><code>${esc(i.source_digest || "—")}</code></dd><dt>Build identity</dt><dd><code>${esc(JSON.stringify(i.build_identity))}</code></dd><dt>Configuration</dt><dd><code>${esc(JSON.stringify(i.configuration))}</code></dd><dt>Dependencies</dt><dd>${nl((i.dependencies || []).map(d => typeof d === "string" ? d : `${d.name} ${d.version || ""}`))}</dd><dt>Runtime environment</dt><dd><code>${esc(JSON.stringify(i.runtime_environment))}</code></dd><dt>Parameters</dt><dd><code>${esc(JSON.stringify(i.parameters))}</code></dd><dt>Intended use</dt><dd>${esc(i.intended_use)}</dd><dt>Threat assumptions</dt><dd>${esc(i.threat_assumptions)}</dd><dt>Replaces</dt><dd>${i.parent ? `<a href="#/p/${pid}/implementations/${i.parent.id}">${esc(i.parent.name)} ${esc(i.parent.version)}</a>` : "—"}</dd><dt>Implements recommendation</dt><dd>${i.recommendation ? `<a href="#/p/${pid}/recommendations/${i.recommendation.id}">${esc(i.recommendation.title)}</a>` : "—"}</dd><dt>Notes</dt><dd>${esc(i.notes)}</dd></dl></div>
  <div class="panel"><h2>Compatibility (static check — not a security boundary)</h2><p>${badge(c.status || "unchecked")} <span class="muted small">${esc(c.note || "")}</span></p>${nl(c.report)}${(c.problems || []).length ? `<div class="callout bad"><b>Unsupported:</b>${nl(c.problems)}Use the results-import path or the customer-side runner.</div>` : ""}${(c.warnings || []).length ? `<div class="callout">${nl(c.warnings)}</div>` : ""}</div>
  </div><div>
  <div class="panel"><h2>Inventory facts for this version</h2><table>${(i.inventory || []).map(x => `<tr><td>${esc(x.category)}</td><td>${esc(x.name)} ${esc(x.version || "")}</td><td>${badge(x.provenance)}</td></tr>`).join("") || '<tr><td class="muted">none</td></tr>'}</table><p class="small muted">user-reported · detected · independently tested. Naming an algorithm says nothing about the implementation's security.</p></div>
  <div class="panel"><h2>Evidence</h2><table><tr><th>#</th><th>Mode</th><th>Classification</th><th>Labels</th><th>Failing</th></tr>${i.runs.map(r => `<tr class="clickable" tabindex="0" ${on("click", () => location.hash = `#/p/${pid}/runs/${r.id}`)}><td>${r.sequence}</td><td>${esc(r.execution_mode)}${r.duplicate_of_run_id ? ' <span class="badge">duplicate</span>' : ""}${r.stale_reason ? ' <span class="badge b-inconclusive">stale</span>' : ""}</td><td>${st(r.classification)}</td><td>${labels(r.evidence_labels)}</td><td class="bad small">${esc(r.scenarios.filter(s => s.pass === false).map(s => s.id).join(", "))}</td></tr>`).join("") || '<tr><td colspan=5 class="muted">No runs yet — go to Tests & Benchmarks.</td></tr>'}</table>
  <p><a href="#/p/${pid}/tests?impl=${iid}"><button class="ghost sm">Run tests against this version</button></a></p></div>
  <div class="panel"><h2>Findings</h2>${i.findings.length ? `<ul class="tight">${i.findings.map(f => `<li><a href="#/p/${pid}/findings/${f.id}">${esc(f.title)}</a> ${badge(f.status)} <span class="tag">${esc(f.role)}</span></li>`).join("")}</ul>` : '<p class="muted">none</p>'}${i.children.length ? `<h3>Superseded by</h3>${i.children.map(ch => `<a href="#/p/${pid}/implementations/${ch.id}">${esc(ch.name)} ${esc(ch.version)}</a> ${badge(ch.status)}<br>`).join("")}` : ""}</div>
  ${snap ? `<div class="panel"><h2>Source snapshot</h2><p class="small muted">${esc(snap.artifact.filename)} · ${snap.artifact.size} B · <code>${esc(snap.artifact.sha256.slice(0, 20))}…</code> ${dlBtn(`/api/projects/${pid}/artifacts/${snap.artifact.id}/download`, snap.artifact.filename, "download")}</p><details><summary>adapter.py (read-only)</summary><pre>${esc(snap.adapter_source)}</pre></details></div>` : ""}
  </div></div>`;
});

// ---- tests & benchmarks
route(/^\/p\/([^/]+)\/tests$/, async (pid, q) => {
  projNav(pid, "/tests");
  const [tests, impls, runs, runners, keys] = await Promise.all([api(`/api/projects/${pid}/tests`), api(`/api/projects/${pid}/implementations`), api(`/api/projects/${pid}/runs`), api("/api/runners"), api(`/api/projects/${pid}/trusted-keys`)]);
  const core = tests.filter(t => t.fixture === "signature_library");  // toolkit tools run from Research & Experiments
  const selT = q.test || (core[0] && core[0].id), selI = q.impl || (impls.slice().reverse().find(i => i.compatibility?.status === "compatible") || impls[impls.length - 1] || {}).id;
  let pf = null; if (selT && selI) { try { pf = await api(`/api/projects/${pid}/tests/${selT}/preflight?implementation_id=${selI}&execution_mode=platform_sandbox`); } catch (e) { pf = {error: e.message}; } }
  const sandbox = runners.find(r => r.kind === "platform_sandbox");
  const runnerKeys = keys.filter(k => k.purpose === "customer_runner" && k.status === "active");
  return `<h1>Tests &amp; Benchmarks</h1><p class="sub">One versioned test definition, two execution modes with the same result schema. This is a library-level signature test; it does not validate a firmware-update or payment protocol.</p>
  <div class="grid g2"><div class="panel elev"><h2>A. Platform sandbox</h2><div class="row"><div style="flex:1"><label>Test definition</label><select ${on("change", function () { location.hash = `#/p/${pid}/tests?test=${this.value}&impl=${selI || ""}`; })}>${core.map(t => `<option value="${t.id}" ${t.id === selT ? "selected" : ""}>${esc(t.name)} — ${esc(t.test_id)}@${esc(t.version)}</option>`).join("")}</select></div><div style="flex:1"><label>Implementation version</label><select ${on("change", function () { location.hash = `#/p/${pid}/tests?test=${selT || ""}&impl=${this.value}`; })}>${impls.map(i => `<option value="${i.id}" ${i.id === selI ? "selected" : ""}>${esc(i.name)} ${esc(i.version)} (${esc(i.compatibility?.status || "unchecked")})</option>`).join("")}</select></div></div>
  ${pf && !pf.error ? `<h3>Before execution</h3><dl class="kv"><dt>Implementation</dt><dd>${esc(pf.implementation.name)} ${esc(pf.implementation.version)} · digest ${short(pf.implementation.source_digest)} · ${esc(pf.implementation.adapter_kind)}</dd><dt>Test definition</dt><dd><code>${esc(pf.test.test_id)}@${esc(pf.test.version)}</code> · fixture ${esc(pf.test.fixture)} · definition sha256 ${short(pf.test.definition_sha256)}</dd><dt>Runner</dt><dd>${esc(pf.runner.kind)} ${esc(pf.runner.version)}</dd><dt>Inputs</dt><dd><code>${esc(JSON.stringify(pf.inputs))}</code></dd><dt>Acceptance criteria</dt><dd>${nl(pf.test.acceptance_criteria)}</dd><dt>Requirements applied</dt><dd>${nl(pf.requirements.map(r => `${r.name}: ${r.metric} ${r.operator} ${r.threshold} (${r.applies_to})`))}</dd><dt>Resource limits</dt><dd><code>${esc(JSON.stringify(pf.resource_limits))}</code></dd><dt>Execution mode</dt><dd>${esc(pf.execution_mode)} · networking ${esc(pf.networking)} · pinned dependencies only</dd><dt>Results will be</dt><dd>${prov(pf.result_provenance)}</dd></dl>
  ${pf.can_execute ? `<p><button ${on("click", () => act(() => api(`/api/projects/${pid}/runs`, {method: "POST", body: {test_definition_id: selT, implementation_id: selI, wait: true}}), "Run completed — see run records below"))}>Run in platform sandbox</button> <span class="muted small">${esc(sandbox ? sandbox.description : "")}</span></p>` : `<div class="callout bad"><b>Cannot execute:</b> ${esc(pf.problems.join("; "))}</div>`}` : pf ? `<div class="callout bad">${esc(pf.error)}</div>` : '<p class="muted">Import an implementation and define a test first.</p>'}</div>
  <div class="panel"><h2>B. Customer-side runner</h2><p class="small">Run the same versioned test on your machine; source and private keys stay local. Upload the signed bundle here. Trusted runner keys: ${runnerKeys.length ? runnerKeys.map(k => `<code>${esc(k.name)}</code>`).join(", ") : '<span class="warn">none registered — add one in Evidence → Trusted keys</span>'}.</p>
  <pre>python -m iel_tools.runner keygen --out runner_key.pem
python -m iel_tools.runner run --project ${esc(pid)} --impl-name &lt;name&gt; --impl-version &lt;version&gt; \\
  --adapter ./adapter.py --test ${esc((core.find(t => t.id === selT) || {}).test_id || "signature-library-core")} --test-version ${esc((core.find(t => t.id === selT) || {}).version || "1")} --key runner_key.pem --out bundle.json</pre>
  <form ${on("submit", async (e) => { let bundle; try { bundle = await readJsonFile(e.target.bundle); } catch (err) { return toast(err.message, true); } act(async () => { const r = await api(`/api/projects/${pid}/runs/import-bundle`, {method: "POST", body: {bundle}}); toast(r.import_info.duplicate_of ? "Imported but flagged DUPLICATE (not counted as a new run)" : r.import_info.stale.length ? "Imported but flagged stale: " + r.import_info.stale.join("; ") : "Bundle verified and imported"); location.hash = `#/p/${pid}/runs/${r.id}`; }, "Bundle processed"); })}><label>Signed bundle (bundle.json)</label><input type="file" name="bundle" accept=".json"><p><button class="ghost">Verify &amp; import bundle</button></p></form>
  <p class="small muted">Before acceptance the platform checks the DSSE signature, the expected signer (trust policy), artifact digests, schema and project/implementation binding; duplicates (same run id) and stale submissions are flagged, not counted. A signature proves integrity and attribution, not that the claimed environment was genuine.</p>
  <h3>Existing results (unsigned)</h3><form ${on("submit", async (e) => { let doc; try { doc = await readJsonFile(e.target.doc); } catch (err) { return toast(err.message, true); } act(() => api(`/api/projects/${pid}/runs/import-results`, {method: "POST", body: {implementation_id: e.target.impl.value, test_definition_id: selT, document: doc, illustrative: e.target.illus.checked}}), "Results imported (labelled imported)"); })}><div class="row"><select name="impl" style="max-width:260px">${impls.map(i => `<option value="${i.id}">${esc(i.name)} ${esc(i.version)}</option>`).join("")}</select><input type="file" name="doc" accept=".json" style="max-width:260px"><label style="margin:0"><input type="checkbox" name="illus"> illustrative</label><button class="ghost sm">Import results</button></div></form></div></div>
  <div class="panel"><h2>Run records</h2><table><tr><th>#</th><th>Test</th><th>Implementation</th><th>Mode</th><th>Provenance</th><th>Classification</th><th>Labels</th><th>Failing</th><th>Flags</th><th>When</th></tr>
  ${runs.slice().reverse().map(r => `<tr class="clickable" tabindex="0" ${on("click", () => location.hash = `#/p/${pid}/runs/${r.id}`)}><td>${r.sequence}</td><td><code>${esc(r.test_label)}</code></td><td>${esc(r.implementation_label)}</td><td>${esc(r.execution_mode)}</td><td>${prov(r.provenance)}</td><td>${st(r.classification)}</td><td>${labels(r.evidence_labels)}</td><td class="bad small">${esc(r.scenarios.filter(s => s.pass === false).map(s => s.id).join(", "))}</td><td class="small">${r.duplicate_of_run_id ? '<span class="badge">duplicate</span>' : ""}${r.stale_reason ? `<span class="badge b-inconclusive" title="${esc(r.stale_reason)}">stale</span>` : ""}${r.supersedes_run_id ? '<span class="badge">correction</span>' : ""}${r.experiment_proposal_id ? '<span class="badge">experiment</span>' : ""}</td><td class="muted small">${when(r.created_at)}</td></tr>`).join("") || '<tr><td colspan=10 class="muted">No runs.</td></tr>'}</table>
  <div class="row" style="margin-top:10px"><span class="muted small">Compare two completed runs:</span><select id="cb" style="max-width:300px">${runs.filter(r => r.status === "completed").map(r => `<option value="${r.id}">#${r.sequence} ${esc(r.implementation_label)} [${esc(r.execution_mode)}]</option>`).join("")}</select><select id="cc" style="max-width:300px">${runs.filter(r => r.status === "completed").map(r => `<option value="${r.id}">#${r.sequence} ${esc(r.implementation_label)} [${esc(r.execution_mode)}]</option>`).join("")}</select><button class="ghost sm" ${on("click", () => location.hash = `#/p/${pid}/compare?b=${$("#cb").value}&c=${$("#cc").value}`)}>Compare</button></div></div>
  <div class="panel"><h2>Test definitions</h2><table><tr><th>Test</th><th>Version</th><th>Fixture</th><th>Definition</th><th>Acceptance criteria</th><th>Resource limits</th></tr>${tests.map(t => `<tr><td><b>${esc(t.name)}</b><br><span class="muted small">${esc(t.description)}</span></td><td><code>${esc(t.test_id)}@${esc(t.version)}</code></td><td><code>${esc(t.fixture)}</code></td><td class="small"><code>${esc(JSON.stringify(t.definition))}</code></td><td class="small">${nl(t.acceptance_criteria)}</td><td class="small"><code>${esc(JSON.stringify(t.resource_limits))}</code></td></tr>`).join("")}</table></div>`;
});
route(/^\/p\/([^/]+)\/runs\/([^/]+)$/, async (pid, rid) => {
  projNav(pid, "/tests");
  const r = await api(`/api/projects/${pid}/runs/${rid}`);
  const mdef = (k) => r.metric_definitions[k] || Object.entries(r.metric_definitions).find(([kk]) => kk.endsWith("*") && k.startsWith(kk.slice(0, -1)))?.[1] || "";
  return `<h1>Run #${r.sequence} ${st(r.classification)} <span class="badge">${esc(r.execution_mode)}</span> ${prov(r.provenance)}</h1><p class="sub"><code>${esc(r.test.test_id)}@${esc(r.test.version)}</code> ${esc(r.test.name)} · ${esc(r.implementation.name)} ${esc(r.implementation.version)} · runner ${esc(r.runner_kind)} ${esc(r.runner_version)} · fixture ${esc(r.fixture_version)} · ${when(r.created_at)}</p>
  <p>Labels: ${labels(r.evidence_labels)}</p>
  ${r.duplicate_of ? `<div class="callout"><b>Duplicate submission:</b> same runner run id as <a href="#/p/${pid}/runs/${r.duplicate_of.id}">run #${r.duplicate_of.sequence}</a>; not counted as a new run.</div>` : ""}${r.stale_reason ? `<div class="callout"><b>Stale submission:</b> ${esc(r.stale_reason)}</div>` : ""}
  ${r.execution_mode === "customer_runner" ? `<div class="callout info">Customer-side execution. Receipt time ${when(r.received_at)} is recorded separately from the runner-reported execution time ${esc(r.runner_reported_executed_at || "—")}. The signature establishes integrity and attribution under the trust policy, not that the reported environment was genuine.</div>` : ""}
  ${r.inputs?.control ? `<div class="callout info"><b>${esc(r.inputs.control.kind)} control.</b> ${esc(r.inputs.control.name)}${r.inputs.control.source ? ` — ${esc(r.inputs.control.source)}` : ""}${r.inputs.control.planted ? `<br>Planted: ${esc(r.inputs.control.planted.join("; "))}` : ""}</div>` : ""}${r.inputs?.tool && !r.inputs?.control ? `<div class="callout info"><b>Toolkit run:</b> ${esc(r.inputs.record_name || r.inputs.tool)}</div>` : ""}
  ${r.provenance === "illustrative" ? '<div class="callout demo">ILLUSTRATIVE DATA — demonstration numbers, not a measurement.</div>' : ""}${r.supersedes_run_id ? `<div class="callout info">Correction of <a href="#/p/${pid}/runs/${r.supersedes_run_id}">an earlier run</a>: ${esc(r.correction_note)}</div>` : ""}${r.superseded_by.length ? `<div class="callout">Superseded by ${r.superseded_by.map(s => `<a href="#/p/${pid}/runs/${s.id}">run #${s.sequence}</a>`).join(", ")} (this record is unchanged).</div>` : ""}
  ${r.failures.length ? `<div class="callout bad"><b>Failures</b>${nl(r.failures)}</div>` : ""}
  <div class="grid g2"><div>
  <div class="panel"><h2>Scenarios</h2><table><tr><th>Scenario</th><th>Class</th><th>Expected</th><th>Observed</th><th></th></tr>${r.scenarios.map(s => `<tr><td>${esc(s.name || s.id)}<br><span class="muted small">${esc(s.id)} ${esc(s.detail || "")}</span></td><td class="small">${esc(s.class || "")}</td><td>${esc(s.expected)}</td><td>${esc(s.observed)}</td><td>${passmark(s.pass)}</td></tr>`).join("") || '<tr><td class="muted">none</td></tr>'}</table></div>
  <div class="panel"><h2>Requirement evaluation</h2><table>${r.requirement_results.map(x => `<tr><td>${esc(x.name)}</td><td><code>${esc(x.metric)} ${esc(x.operator)} ${x.threshold} ${esc(x.unit)}</code></td><td class="num">${fmt(x.observed)}</td><td>${passmark(x.pass)} <span class="tag">${esc(x.note || "")}</span></td></tr>`).join("") || '<tr><td class="muted">not applicable to this run</td></tr>'}</table></div>
  <div class="panel"><h2>Metrics (with measurement definitions)</h2><table>${Object.entries(r.metrics).map(([k, v]) => `<tr><td><code>${esc(k)}</code></td><td class="num">${typeof v === "object" ? `<code class="small">${esc(JSON.stringify(v))}</code>` : fmt(v)}</td><td class="muted small">${esc(mdef(k))}</td></tr>`).join("")}</table></div></div>
  <div><div class="panel"><h2>Provenance &amp; reproducibility</h2><dl class="kv"><dt>Inputs / seeds</dt><dd><code>${esc(JSON.stringify(r.inputs))}</code></dd><dt>Resource limits</dt><dd><code>${esc(JSON.stringify(r.resource_limits))}</code></dd><dt>Repeat count</dt><dd>${r.repeat_count}</dd><dt>Environment</dt><dd>${json(r.environment)}</dd><dt>Commands</dt><dd>${json(r.commands)}</dd><dt>Artifact hashes</dt><dd><code class="small">${esc(JSON.stringify(r.artifact_hashes))}</code> ${r.raw_artifact ? (r.raw_artifact_integrity_ok ? '<span class="ok">integrity ok</span>' : '<span class="bad">INTEGRITY MISMATCH</span>') : ""}</dd><dt>Raw output</dt><dd>${r.raw_artifact ? dlBtn(`/api/projects/${pid}/artifacts/${r.raw_artifact.id}/download`, r.raw_artifact.filename, r.raw_artifact.filename + " (" + r.raw_artifact.size + " B)") : "—"}</dd><dt>Evidence bundle</dt><dd>${r.bundle ? `<a href="#/p/${pid}/bundles/${r.bundle.id}">${esc(r.bundle.kind)} bundle</a> · signer ${esc(r.bundle.signer_name || "")} ${r.bundle.bundle_artifact ? dlBtn(`/api/projects/${pid}/artifacts/${r.bundle.bundle_artifact.id}/download`, r.bundle.bundle_artifact.filename, "download bundle") : ""}` : '<span class="na">none</span>'}</dd><dt>Job</dt><dd>${r.job ? `${badge(r.job.status)} ${esc(r.job.error || "")}` : "—"}</dd></dl>
  ${r.execution_mode !== "platform_sandbox" && !r.duplicate_of ? `<p><button class="ghost sm" ${on("click", () => act(() => api(`/api/projects/${pid}/runs/${rid}/replay?wait=true`, {method: "POST"}), "Replay executed; label added only if outcomes match"))}>Independently replay in platform sandbox</button></p>` : ""}</div>
  <div class="panel"><h2>Limitations &amp; exclusions</h2>${nl(r.limitations)}${r.exclusions.length ? `<h3>Exclusions</h3>${nl(r.exclusions)}` : ""}</div>
  <div class="panel"><h2>Raw output</h2>${r.raw ? `<details><summary>Show raw JSON</summary>${json(r.raw)}</details>` : '<p class="muted">none</p>'}</div></div></div>`;
});
route(/^\/p\/([^/]+)\/compare$/, async (pid, q) => {
  projNav(pid, "/tests");
  if (!q.b || !q.c) { location.hash = `#/p/${pid}/tests`; return ""; }
  const c = await api(`/api/projects/${pid}/compare?baseline_run_id=${q.b}&candidate_run_id=${q.c}`);
  return `<h1>Compare runs</h1><p class="sub">Baseline run #${c.baseline.sequence} (${esc(c.baseline.implementation.name)} ${esc(c.baseline.implementation.version)}, ${esc(c.baseline.execution_mode)}) vs candidate run #${c.candidate.sequence} (${esc(c.candidate.implementation.name)} ${esc(c.candidate.implementation.version)}, ${esc(c.candidate.execution_mode)})</p>
  ${c.comparison_limits.length ? `<div class="callout"><b>Comparison limits:</b>${nl(c.comparison_limits)}</div>` : '<div class="callout ok">Same test definition, execution mode and environment: numeric deltas are meaningful within the stated measurement definitions.</div>'}
  <div class="grid g3"><div class="panel"><h3>Previously failing cases</h3>${c.previously_failing_now.length ? `<table>${c.previously_failing_now.map(x => `<tr><td><code>${esc(x.id)}</code></td><td>${passmark(x.candidate)}</td></tr>`).join("")}</table>` : '<p class="muted">none</p>'}</div><div class="panel"><h3>New regressions</h3>${c.new_regressions.length ? `<ul class="tight bad">${c.new_regressions.map(x => `<li>${esc(x)}</li>`).join("")}</ul>` : '<p class="ok">none</p>'}</div><div class="panel"><h3>Remaining uncertainty</h3>${nl(c.remaining_uncertainty)}</div></div>
  <div class="panel"><h2>Correctness</h2><table><tr><th>Scenario</th><th>Baseline</th><th>Candidate</th></tr>${c.scenarios.map(s => `<tr><td><code>${esc(s.id)}</code></td><td>${passmark(s.baseline)}</td><td>${passmark(s.candidate)}</td></tr>`).join("")}</table></div>
  <div class="panel"><h2>Performance &amp; resource use</h2><table><tr><th>Metric</th><th class="num">Baseline</th><th class="num">Candidate</th><th class="num">Δ</th><th class="num">Δ %</th><th>Definition</th></tr>${c.metrics.filter(m => typeof m.baseline !== "object" && typeof m.candidate !== "object").map(m => `<tr><td><code>${esc(m.metric)}</code></td><td class="num">${fmt(m.baseline)}</td><td class="num">${fmt(m.candidate)}</td><td class="num">${fmt(m.delta)}</td><td class="num">${m.delta_pct == null ? "—" : m.delta_pct.toFixed(1) + "%"}</td><td class="muted small">${esc(m.definition)}</td></tr>`).join("")}</table></div>
  <div class="panel"><h2>Requirements</h2><table><tr><th>Requirement</th><th>Baseline</th><th>Candidate</th></tr>${c.requirements.candidate.map((x, i) => `<tr><td>${esc(x.name)}</td><td>${fmt(c.requirements.baseline[i]?.observed)} ${passmark(c.requirements.baseline[i]?.pass)}</td><td>${fmt(x.observed)} ${passmark(x.pass)}</td></tr>`).join("") || '<tr><td class="muted">none</td></tr>'}</table></div>`;
});

// ---- research & experiments
route(/^\/p\/([^/]+)\/research$/, async (pid, q) => {
  projNav(pid, "/research");
  const tab = q.tab || "experiments";
  const [status, sources, props, attack, runs] = await Promise.all([api(`/api/projects/${pid}/research/status`), api(`/api/projects/${pid}/research/sources`), api(`/api/projects/${pid}/experiments`), api(`/api/projects/${pid}/attack-assessments`), api(`/api/projects/${pid}/runs`)]);
  let body = "";
  if (tab === "experiments") body = `<div class="callout info">Autoresearcher: ${esc(status.note)} ${esc(status.monitoring)}. Proposals need human approval; only allowlisted fixtures execute; AI-generated code never runs.</div>
  <p><button ${on("click", () => act(() => api(`/api/projects/${pid}/experiments/propose`, {method: "POST"}), "Proposals generated from findings and sources"))}>Propose experiments</button></p>
  <div class="panel"><table><tr><th>Proposal</th><th>Claim status</th><th>Executable?</th><th>Status</th><th>Protocol</th><th>Result</th></tr>${props.map(p => `<tr class="clickable" tabindex="0" ${on("click", () => location.hash = `#/p/${pid}/experiments/${p.id}`)}><td><b>${esc(p.title)}</b><br><span class="muted small">${esc(p.research_question)}</span></td><td>${badge(p.claim_status)}</td><td>${p.allowlisted_fixture ? `<code>${esc(p.allowlisted_fixture)}</code>` : '<span class="warn small">proposal only</span>'}</td><td>${badge(p.status)}</td><td>${p.current_protocol_version ? "v" + p.current_protocol_version : "—"}</td><td class="small">${esc(p.result_summary || "")}</td></tr>`).join("") || '<tr><td colspan=6 class="muted">No proposals. Submit a source or open a finding, then “Propose experiments”.</td></tr>'}</table></div>`;
  else if (tab === "sources") body = `<div class="grid g2"><div class="panel"><h2>Submit research source</h2><p class="small muted">Uploaded documents are untrusted input: stored, hashed and pattern-matched; never executed or followed as instructions.</p><form ${on("submit", (e) => { const b = Object.fromEntries(new FormData(e.target).entries()); b.is_demo = !!b.is_demo; b.wait = true; if (!b.url) delete b.url; if (!b.content) delete b.content; act(() => api(`/api/projects/${pid}/research/sources`, {method: "POST", body: b}), "Source reviewed; finding created"); })}><label>Title</label><input name="title"><label>URL (fetched server-side as text) — or paste text below</label><input name="url"><label>Document text</label><textarea name="content"></textarea><label><input type="checkbox" name="is_demo"> label as demonstration</label><p><button>Submit &amp; review</button></p></form></div>
  <div class="panel"><h2>Sources</h2><table>${sources.map(s => `<tr><td>${esc(s.title)} ${demo(s.is_demo)}<br><span class="muted small">${esc(s.source_type)} · sha256 ${esc(s.content_sha256.slice(0, 12))}… · ${esc(s.extraction_method)}</span></td><td>${badge(s.review_status)}</td></tr>`).join("") || '<tr><td class="muted">none</td></tr>'}</table></div></div>`;
  else if (tab === "toolkit") body = await toolkitView(pid, q);
  else if (tab === "portfolio") body = await portfolioView();
  else body = `<p class="small muted">Every assessment is tied to an exact target and version. Breaking time is never derived from signing/verification speed; toy experiments are never extrapolated to production; no date for practical quantum attacks is asserted. Passing tests does not prove an implementation secure.</p>
  ${Object.entries(attack.categories).map(([k, label]) => `<h2>${esc(label)}</h2>${attack.items.filter(a => a.category === k).map(a => `<div class="panel"><div class="row"><b>${esc(a.target)}</b> ${a.target_version ? `<code>${esc(a.target_version)}</code>` : ""} ${badge(a.attack_model)} ${demo(a.is_demo)} <span class="tag right">reviewed ${esc(a.review_date || "—")}</span></div>
  <dl class="kv"><dt>Objective / attacker</dt><dd>${esc(a.objective)} — ${esc(a.attacker_capabilities)}</dd><dt>Method &amp; source</dt><dd>${esc(a.method)}<br><span class="muted small">${esc(a.source)}</span></dd><dt>Parameters</dt><dd><code>${esc(JSON.stringify(a.target_parameters))}</code></dd><dt>Measured components</dt><dd>${a.measured_components ? `<code class="small">${esc(JSON.stringify(a.measured_components))}</code> ${a.run_id ? `<a href="#/p/${pid}/runs/${a.run_id}">run</a>` : ""}` : '<span class="na">none</span>'}</dd><dt>Expected work</dt><dd><b>${esc(a.display_work)}</b>${a.expected_work?.estimation_method ? `<br><span class="muted small">${esc(a.expected_work.estimation_method)}</span>` : ""}</dd>${a.probability_model ? `<dt>Probability model</dt><dd>${esc(a.probability_model)}</dd>` : ""}<dt>Hardware / parallelisation / overhead</dt><dd>${esc(a.hardware_assumptions)} ${esc(a.parallelization)} ${esc(a.overhead_assumptions)}</dd><dt>Compute price (optional)</dt><dd>${a.cost ? `${a.cost.core_hours.toPrecision(3)} core-hours ≈ $${a.cost.usd.toPrecision(3)} <span class="muted small">${esc(a.cost.note)}</span>` : '<span class="na">not applied</span>'} <button class="sm ghost" ${on("click", () => { const v = prompt("USD per core-hour", "0.04"); if (v) act(() => api(`/api/projects/${pid}/attack-assessments/${a.id}/price`, {method: "PATCH", body: {compute_price: {unit: "core_hour", price_usd: parseFloat(v)}}}), "Price set"); })}>set price</button></dd><dt>Uncertainty / limits</dt><dd>${esc(a.uncertainty)} ${esc(a.applicability_limits)}</dd></dl></div>`).join("") || '<p class="muted">No entries.</p>'}`).join("")}
  <div class="panel"><h3>Derive an estimate from a measured toy run</h3><div class="row"><select id="estrun" style="max-width:380px">${runs.filter(r => r.metrics.iterations_per_second).map(r => `<option value="${r.id}">#${r.sequence} ${fmt(r.metrics.iterations_per_second)} it/s</option>`).join("")}</select><input id="estbits" type="number" value="64" style="max-width:100px"> bits <button class="ghost sm" ${on("click", () => act(() => api(`/api/projects/${pid}/attack-assessments/estimate-from-run`, {method: "POST", body: {measured_run_id: $("#estrun").value, target_modulus_bits: parseInt($("#estbits").value)}}), "Assessment recorded"))}>Estimate</button><span class="muted small">Refuses targets outside the toy range (“No defensible estimate available”).</span></div></div>`;
  return `<h1>Research &amp; Experiments</h1>${tabs(`#/p/${pid}/research`, tab, [["experiments", "Experiment proposals"], ["sources", "Research sources"], ["attack", "Attack assessments"], ["toolkit", "Cryptanalysis toolkit"], ["portfolio", "Research portfolio"]])}${body}`;
});
route(/^\/p\/([^/]+)\/experiments\/([^/]+)$/, async (pid, eid) => {
  projNav(pid, "/research");
  const p = await api(`/api/projects/${pid}/experiments/${eid}`);
  const sec = (t, c) => `<h3>${t}</h3><p>${c}</p>`;
  return `<h1>${esc(p.title)} ${badge(p.status)} ${badge(p.claim_status)}</h1><p class="sub">proposed by ${esc(p.proposed_by)} · ${p.allowlisted_fixture ? `allowlisted fixture <code>${esc(p.allowlisted_fixture)}</code>` : '<span class="warn">proposal only — no allowlisted fixture, cannot execute</span>'} · target class ${esc(p.target_class)}${p.finding ? ` · finding <a href="#/p/${pid}/findings/${p.finding.id}">${esc(p.finding.title)}</a>` : ""}</p>
  <div class="grid g2"><div class="panel">${sec("Research question", esc(p.research_question))}${sec("Motivation", esc(p.motivation))}<h3>Source references</h3>${nl((p.source_references || []).map(s => `${s.kind || "source"}: ${s.title || s.id}`))}<h3>Affected implementation</h3><p>${p.affected_implementation ? `<a href="#/p/${pid}/implementations/${p.affected_implementation.id}">${esc(p.affected_implementation.name)} ${esc(p.affected_implementation.version)}</a>` : "—"}</p>${sec("Falsifiable hypothesis", esc(p.hypothesis))}${sec("Baseline and controls", esc(p.baseline_controls))}${sec("Procedure", esc(p.procedure))}<h3>Required tools</h3>${nl(p.required_tools)}<h3>Outcomes</h3><dl class="kv"><dt>Success</dt><dd>${esc(p.outcomes?.success)}</dd><dt>Failure</dt><dd>${esc(p.outcomes?.failure)}</dd><dt>Inconclusive</dt><dd>${esc(p.outcomes?.inconclusive)}</dd></dl><h3>Budget</h3><p>${esc(JSON.stringify(p.budget))}</p><h3>Required artifacts</h3>${nl(p.required_artifacts)}${sec("Safety and authorization boundaries", esc(p.safety_boundaries))}${sec("What it could establish", esc(p.can_establish))}${sec("What it could not establish", esc(p.cannot_establish))}<h3>Parameters</h3><code>${esc(JSON.stringify(p.parameters))}</code></div>
  <div><div class="panel"><h2>Approval &amp; protocol versions</h2><p class="small muted">Approval freezes the proposal as a versioned protocol. Amendments create new versions; earlier protocols and raw results are never overwritten. Acceptance criteria change only through this human path.</p>
  ${p.status === "proposed" ? `<div class="row"><input id="enote" placeholder="review note" style="max-width:280px"><button ${on("click", () => act(() => api(`/api/projects/${pid}/experiments/${eid}/decide`, {method: "POST", body: {decision: "approved", note: $("#enote").value}}), "Approved: protocol version frozen"))}>Approve (reviewer)</button><button class="danger" ${on("click", () => act(() => api(`/api/projects/${pid}/experiments/${eid}/decide`, {method: "POST", body: {decision: "rejected", note: $("#enote").value}}), "Rejected"))}>Reject</button></div>` : ""}
  ${p.status === "approved" && p.allowlisted_fixture ? `<p><button ${on("click", () => act(() => api(`/api/projects/${pid}/experiments/${eid}/execute?wait=true`, {method: "POST"}), "Executed in the platform sandbox"))}>Execute protocol v${p.current_protocol_version}</button></p>` : ""}
  ${p.status === "executed" ? `<div class="row"><input id="rnote" placeholder="review note" style="max-width:280px"><button class="ghost" ${on("click", () => act(() => api(`/api/projects/${pid}/experiments/${eid}/review`, {method: "POST", body: {decision: "reviewed", note: $("#rnote").value}}), "Result reviewed"))}>Mark result reviewed</button></div>` : ""}
  ${["approved", "executed", "reviewed", "rejected"].includes(p.status) ? `<details style="margin-top:8px"><summary>Amend (creates a new proposal version for re-approval)</summary><form ${on("submit", (e) => { let ch; try { ch = JSON.parse(e.target.changes.value); } catch { return toast("changes must be JSON", true); } act(() => api(`/api/projects/${pid}/experiments/${eid}/amend`, {method: "POST", body: {changes: ch, note: e.target.note.value}}), "Amended; awaiting re-approval"); })}><label>Changes (JSON of protocol fields, e.g. {"parameters": {"max_extra_bytes": 128}})</label><textarea name="changes">{}</textarea><label>Note</label><input name="note"><p><button class="ghost sm">Submit amendment</button></p></form></details>` : ""}
  <table>${p.protocol_versions.map(v => `<tr><td>v${v.version}</td><td class="mono">${esc(v.protocol_sha256.slice(0, 16))}…</td><td>${esc(v.note)}</td><td class="muted small">${when(v.created_at)}</td></tr>`).join("") || '<tr><td class="muted">no approved protocol yet</td></tr>'}</table>
  <h3>Decisions</h3><table>${p.approvals.map(a => `<tr><td>${badge(a.decision)}</td><td>${esc(a.note)}</td><td class="muted small">${when(a.created_at)}</td></tr>`).join("") || '<tr><td class="muted">none</td></tr>'}</table></div>
  <div class="panel"><h2>Executed results</h2>${p.result_summary ? `<div class="callout ${p.status === "reviewed" ? "ok" : "info"}">${esc(p.result_summary)}</div>` : '<p class="muted">Not executed. Proposals are kept separate from results.</p>'}<table>${p.runs.map(r => `<tr class="clickable" tabindex="0" ${on("click", () => location.hash = `#/p/${pid}/runs/${r.id}`)}><td>#${r.sequence}</td><td>protocol v${r.protocol_version}</td><td>${st(r.classification)}</td><td class="small"><code>${esc(JSON.stringify(r.metrics.by_variant || r.metrics))}</code></td></tr>`).join("")}</table></div></div></div>`;
});


// ---- cryptanalysis-suite toolkit (supporting component; lives under Research & Experiments)
let TOOLKIT = null;
const toolkit = async () => TOOLKIT || (TOOLKIT = await api("/api/toolkit"));
const kindBadge = (k) => `<span class="badge b-ctl-${esc(k)}">${esc(k)} control</span>`;
const suiteBanner = (s) => s.available
  ? `<div class="callout info"><b>Suite connected.</b> <code>${esc(s.version)}</code> · binary SHA-256 <code title="${esc(s.sha256)}">${esc(s.sha256.slice(0, 16))}…</code>. Every run records the exact argv, this hash, the raw JSON and its limitations.</div>`
  : `<div class="callout"><b>Suite not connected.</b> ${esc(s.reason)} Existing evidence remains readable; set <code>IEL_CRAX_BIN</code> to run tools. Nothing is simulated.</div>`;
function toolHeadline(tool, m) {
  const f = (k) => fmt(m[k]);
  switch (tool) {
    case "suite_curve_audit": return `checks ${f("suite_checks_passed")}/${f("suite_checks_total")} · rho ${f("rho_security_bits")} bits`;
    case "suite_curve_estimate": return `rho 2^${f("rho_log2_operations")} ops · IC relevant ${f("index_calculus_relevant")}`;
    case "suite_weak_curve": return `${f("structural_attacks_applicable")} of ${f("checks_evaluated")} structural attacks apply${m.planted_secret_recovered !== undefined ? ` · planted secret recovered ${f("planted_secret_recovered")}` : ""}`;
    case "suite_ecdsa_audit": return `${f("signatures_audited")} sigs · bias ${f("bias_score")} · key recovered ${f("key_recovered")}`;
    case "suite_rsa_key_audit": return `${f("weak_moduli")} weak of ${f("moduli_audited")} (shared ${f("shared_prime_moduli")}, Fermat ${f("fermat_factored")}, Wiener ${f("wiener_factored")})`;
    case "suite_mlwe_estimate": return `cheapest 2^${f("cheapest_log2_cost")}${m.margin_vs_nist_floor_bits !== undefined ? ` · ${m.margin_vs_nist_floor_bits >= 0 ? "+" : ""}${f("margin_vs_nist_floor_bits")} bits vs NIST floor` : ""}`;
    case "suite_generic_rho": return `${f("group_ops")} group ops · ${f("ops_per_sqrt_order")}·√n`;
    case "suite_factor_toy": return `${f("prime_factors")} factors of a ${f("n_bits")}-bit N · complete ${f("complete")}`;
    case "suite_aes_reduced": return `${f("rounds")}-round instance · ${f("pairs_used")} pairs · verified ${f("verified")}`;
    case "suite_hash_kat": return `${f("input_bytes")} B · KAT match ${f("kat_match")}`;
    case "sidechannel_ct_audit": return [m.taint_sites_library !== undefined ? `${f("taint_sites_library")} secret-dependent site(s)${m.taint_sites_harness ? ` (+${f("taint_sites_harness")} harness)` : ""}` : "",
      m.ir_deterministic === 0 ? "Ir: not applicable (A/A varies)" : m.ir_secret_dependent !== undefined ? (m.ir_secret_dependent ? `Ir varies ${f("ir_min")}–${f("ir_max")}` : `Ir constant ${f("ir_min")}`) : ""].filter(Boolean).join(" · ");
  }
  return "";
}
function paramField(p, v) {
  const val = v ?? p.default ?? "";
  const when = p.when ? ` data-when='${esc(JSON.stringify(p.when))}'` : "";
  const help = p.help ? `<span class="muted small">${esc(p.help)}</span>` : "";
  const bounds = p.kind === "int" ? ` (${p.min}–${p.max})` : p.kind === "uint" ? ` (≤ ${p.max} bits)` : p.kind === "uint_list" || p.kind === "signatures" ? ` (≤ ${p.max})` : "";
  let input;
  if (p.kind === "choice") input = `<select name="${esc(p.name)}">${p.choices.map(c => `<option ${String(c) === String(val) ? "selected" : ""}>${esc(c)}</option>`).join("")}</select>`;
  else if (p.kind === "bool") input = `<select name="${esc(p.name)}"><option value="true" ${val === true ? "selected" : ""}>yes</option><option value="false" ${val !== true ? "selected" : ""}>no</option></select>`;
  else if (p.kind === "int") input = `<input name="${esc(p.name)}" type="number" min="${p.min}" max="${p.max}" value="${esc(val)}">`;
  else if (p.kind === "uint_list") input = `<textarea name="${esc(p.name)}" placeholder="one decimal integer per line">${esc(Array.isArray(val) ? val.join("\n") : val)}</textarea>`;
  else if (p.kind === "signatures") input = `<textarea name="${esc(p.name)}" placeholder='[{"r":"…","s":"…","z":"…"}]'>${esc(val && typeof val !== "string" ? JSON.stringify(val) : val)}</textarea>`;
  else input = `<input name="${esc(p.name)}" value="${esc(val)}" ${p.kind === "point" ? 'placeholder="x,y"' : ""}>`;
  return `<div class="pfield"${when}><label>${esc(p.label)}${bounds}${p.required ? " *" : ""}</label>${input}${help}</div>`;
}
function syncWhen(form) {
  if (!form) return;
  const vals = Object.fromEntries(new FormData(form).entries());
  form.querySelectorAll(".pfield[data-when]").forEach(el => { const w = JSON.parse(el.dataset.when); el.style.display = Object.entries(w).every(([k, vs]) => vs.includes(vals[k])) ? "" : "none"; });
}
function collectParams(form, tool) {
  const raw = Object.fromEntries(new FormData(form).entries()), out = {};
  for (const p of tool.params) {
    const el = form.querySelector(`.pfield [name="${p.name}"]`);
    if (!el || el.closest(".pfield").style.display === "none") continue;
    const v = (raw[p.name] ?? "").trim();
    if (v === "") continue;
    if (p.kind === "int") out[p.name] = Number(v);
    else if (p.kind === "bool") out[p.name] = v === "true";
    else if (p.kind === "uint_list") out[p.name] = v.split(/[\s,]+/).filter(Boolean);
    else if (p.kind === "signatures") { try { out[p.name] = JSON.parse(v); } catch { throw new Error(`${p.label}: must be a JSON list of {r, s, z}`); } }
    else out[p.name] = v;
  }
  return out;
}
function toolRun(pid, tool, extra = {}) {
  const form = $("#toolform");
  let body;
  try { body = {tool: tool.id, implementation_id: form.querySelector('[name="implementation_id"]').value, name: form.querySelector('[name="__name"]').value, ...(extra.control ? {control: extra.control} : {params: collectParams(form, tool)})}; } catch (err) { return toast(err.message, true); }
  toast("Running " + tool.title + " … (bounded; a full ECDSA sweep can take ~20 s)");
  return act(async () => { const r = await api(`/api/projects/${pid}/toolkit/run`, {method: "POST", body}); location.hash = `#/p/${pid}/runs/${r.id}`; }, "Tool run recorded");
}
async function toolkitView(pid, q) {
  const [tk, impls, runs] = await Promise.all([toolkit(), api(`/api/projects/${pid}/implementations`), api(`/api/projects/${pid}/toolkit/runs`)]);
  const tool = tk.tools.find(t => t.id === q.tool) || tk.tools.find(t => runs.some(r => r.tool === t.id)) || tk.tools[0];
  const presets = tool.controls.filter(c => !c.generated);
  const preset = q.preset !== undefined ? presets[+q.preset] : null;
  setTimeout(() => syncWhen($("#toolform")));
  const canRun = tool.available && impls.length && !window.IEL_STATIC;
  const base = `#/p/${pid}/research?tab=toolkit`;
  const runControl = (c) => c.generated
    ? `<button class="ghost sm" ${canRun ? "" : "disabled"} ${on("click", () => toolRun(pid, tool, {control: c.id}))}>Run</button>`
    : `<a href="${base}&tool=${tool.id}&preset=${presets.indexOf(c)}"><button class="ghost sm">Load</button></a>`;
  return `<p class="small muted">The Isogeny Labs cryptanalysis suite (<code>crax</code>) and the <code>crypto</code> crate's side-channel harness, connected as ${tk.tools.length} bounded tools, each answering one engineering question (curve parameters, public keys, signature transcripts, parameter sets, secret-dependent control flow). Runs land in Evidence as measured, append-only, platform-signed records. A <b>negative control</b> must come back clean on real material; a <b>positive control</b> plants the weakness the tool claims to find.</p>
  ${suiteBanner(tk.suite)}
  <div class="grid toolgrid"><div class="panel"><h3>Tools</h3>${tk.families.map(fam => `<h3>${esc(fam)}</h3><ul class="tight toollist">${tk.tools.filter(t => t.family === fam).map(t => `<li><a href="${base}&tool=${t.id}" class="${t.id === tool.id ? "cur" : ""}">${esc(t.title)}</a> <span class="muted">${runs.filter(r => r.tool === t.id).length || ""}</span></li>`).join("")}</ul>`).join("")}<details><summary>Execution boundary</summary>${nl(tk.boundary)}</details></div>
  <div><div class="panel"><h2 style="margin-top:0">${esc(tool.title)}</h2><p>${esc(tool.question)}</p>${tool.runner !== "cryptanalysis_suite" ? (tool.available ? `<div class="callout info">Runner <code>${esc(tool.runner)}</code> connected.</div>` : `<div class="callout">Runner <code>${esc(tool.runner)}</code> not connected here: ${esc(String(tool.unavailable_reason).replace(/\.?$/, "."))} Recorded and imported evidence below remains readable.</div>`) : ""}<p class="muted small"><code>${esc(tool.operation)}</code> · acceptance: ${esc(tool.acceptance.join("; "))}</p>
    ${tool.controls.length ? `<h3>Controls</h3><table>${tool.controls.map(c => `<tr><td>${kindBadge(c.kind)}</td><td>${esc(c.name)}${c.generated ? ' <span class="muted small">(fresh material generated server-side)</span>' : ""}</td><td>${runControl(c)}</td></tr>`).join("")}</table>` : ""}
    <h3>${preset ? `Parameters — loaded from control “${esc(preset.name)}”` : "Parameters"}</h3>
    <form id="toolform" ${on("change", function () { syncWhen(this); })} ${on("submit", () => toolRun(pid, tool))}><div class="grid g2">${tool.params.map(p => paramField(p, preset?.params?.[p.name])).join("")}</div>
    <div class="grid g2"><div><label>Run against implementation (the subject the evidence is filed under)</label><select name="implementation_id">${impls.map(i => `<option value="${i.id}">${esc(i.name)} ${esc(i.version)}</option>`).join("")}</select></div><div><label>Record name (optional)</label><input name="__name" value="${preset ? esc("Control: " + preset.name) : ""}"></div></div>
    <p><button ${canRun ? "" : "disabled"}>Run tool</button> <span class="muted small">${window.IEL_STATIC ? "Static demo: browse the recorded runs below." : "Typed fields only — the runner builds argv itself and never accepts a command, flag, path or environment value."}</span></p></form>
    <details><summary>Limitations</summary>${nl(tool.limitations)}</details></div></div></div>
  <div class="panel"><h2>Toolkit evidence in this project</h2><table><tr><th>Run</th><th>Tool</th><th>Record</th><th>Against</th><th>Classification</th><th>Checks</th><th>Headline</th><th>When</th></tr>
  ${runs.map(r => `<tr class="clickable" tabindex="0" ${on("click", () => location.hash = `#/p/${pid}/runs/${r.id}`)}><td>#${r.sequence}</td><td>${esc(tk.tools.find(t => t.id === r.tool)?.title || r.tool)}</td><td>${r.control ? kindBadge(r.control.kind) + " " : ""}${esc(r.record_name)}${r.exclusions?.length ? ' <span class="badge b-demo" title="secret material redacted">redacted</span>' : ""}</td><td class="muted">${esc(r.implementation_label)}</td><td>${st(r.classification)} ${r.provenance ? prov(r.provenance) : ""}</td><td>${passmark(r.overall_pass)} <span class="muted">${r.scenarios_passed}/${r.scenarios_total}</span></td><td class="small">${toolHeadline(r.tool, r.metrics || {})}</td><td class="muted small">${when(r.created_at)}</td></tr>`).join("") || '<tr><td colspan="8" class="muted">No toolkit evidence yet. Pick a tool and run a control first (needs the suite binary).</td></tr>'}</table></div>`;
}

// ---- research portfolio (imported, read-only)
const REGIME_COLOR = {prime: "#76B8F4", char2: "#E8956D", koblitz: "#5FCB8A", koblitz_batch: "#E8B86D"};
const REGIME_LABEL = {prime: "prime field", char2: "random binary", koblitz: "Koblitz", koblitz_batch: "Koblitz, batch"};
function familyChart(fam, rows) {
  const W = 560, H = 230, L = 46, R = 96, T = 14, B = 34;
  const xs = rows.map(r => r.log2_r), ys = rows.map(r => r.ratio_rho);
  const x0 = Math.floor(Math.min(...xs)) - 1, x1 = Math.ceil(Math.max(...xs)) + 1;
  const y0 = 0, y1 = Math.ceil(Math.log2(Math.max(...ys, 2)));
  const X = (v) => L + (v - x0) / (x1 - x0) * (W - L - R), Y = (v) => T + (1 - (Math.log2(v) - y0) / (y1 - y0)) * (H - T - B);
  const series = [...new Set(rows.map(r => r.regime))];
  let g = "";
  for (let k = y0; k <= y1; k++) g += `<line x1="${L}" x2="${W - R}" y1="${Y(2 ** k)}" y2="${Y(2 ** k)}" class="grid"/><text x="${L - 6}" y="${Y(2 ** k) + 4}" text-anchor="end" class="tick">${2 ** k}×</text>`;
  for (let k = Math.ceil(x0 / 4) * 4; k <= x1; k += 4) g += `<text x="${X(k)}" y="${H - B + 16}" text-anchor="middle" class="tick">2^${k}</text>`;
  g += `<line x1="${L}" x2="${W - R}" y1="${Y(1)}" y2="${Y(1)}" class="parity"/><text x="${W - R + 4}" y="${Y(1) + 4}" class="tick">parity (1×)</text>`;
  g += `<text x="${(L + W - R) / 2}" y="${H - 4}" text-anchor="middle" class="tick">subgroup size r (log₂)</text>`;
  for (const s of series) {
    const pts = rows.filter(r => r.regime === s).sort((a, b) => a.log2_r - b.log2_r), c = REGIME_COLOR[s] || "#A4B2C8";
    g += `<polyline fill="none" stroke="${c}" stroke-width="2" points="${pts.map(r => `${X(r.log2_r)},${Y(r.ratio_rho)}`).join(" ")}"/>`;
    for (const r of pts) {
      const tip = `${r.slug}\n${REGIME_LABEL[r.regime] || r.regime}, r ≈ 2^${r.log2_r.toFixed(1)}\n${r.ratio_rho.toFixed(2)}× the matched rho (distance remaining)\nbest recipe: ${r.best_recipe}\nvalidation: ${r.validation_status}`;
      g += `<g class="pt"><circle cx="${X(r.log2_r)}" cy="${Y(r.ratio_rho)}" r="${r.validation_status === "validated" ? 4.5 : 4}" fill="${r.validation_status === "validated" ? c : "#111925"}" stroke="${c}" stroke-width="2"/><circle cx="${X(r.log2_r)}" cy="${Y(r.ratio_rho)}" r="11" fill="transparent"><title>${esc(tip)}</title></circle></g>`;
    }
    const last = pts[pts.length - 1];
    g += `<text x="${X(last.log2_r) + 8}" y="${Y(last.ratio_rho) + 4}" class="dlabel">${esc(REGIME_LABEL[s] || s)}</text>`;
  }
  return `<svg viewBox="0 0 ${W} ${H}" class="chart" role="img" aria-label="${esc(fam.title)}: ratio to matched rho by subgroup size">${g}</svg>`;
}
async function portfolioView() {
  let d; try { d = await api("/api/research/portfolio"); } catch (e) { return `<div class="callout">${esc(e.message)}</div>`; }
  const s = d.source, vg = d.validation_gate?.status_counts || {};
  const fams = Object.entries(d.families), leaders = Object.entries(d.leaders || {});
  return `<p class="small muted">${esc(d.what_this_is || "")}</p>
  <div class="callout info"><b>Imported, read-only.</b> ${prov("imported")} Snapshot of <code>${esc(s.repository)}/${esc(s.path)}</code> at commit <code>${esc(s.commit.slice(0, 12))}</code> (file last changed ${esc(s.file_last_changed)}), SHA-256 <code title="${esc(s.sha256)}">${esc(s.sha256.slice(0, 16))}…</code>. Nothing is recomputed or re-ranked here. Refresh with <code>scripts/import_research_portfolio.py</code>.</div>
  <div class="callout"><b>How to read this.</b> ${esc(d.success_criterion)} The leaderboard is not ${esc((d.what_this_is_not || []).join(", "))}.</div>
  <div class="grid g4"><div class="panel"><div class="stat">${d.rows.length}<small>board rows (curve sizes × families)</small></div></div><div class="panel"><div class="stat">${vg["validated"] ?? 0}<small>rows validated (replay certificate, validator report, matched rho)</small></div></div><div class="panel"><div class="stat">${vg["unvalidated (pre-gate)"] ?? 0}<small>rows unvalidated (pre-gate)</small></div></div><div class="panel"><div class="stat">${leaders.length ? Math.min(...leaders.map(([, l]) => l.ratio_rho)).toFixed(2) + "×" : "—"}<small>closest distance to the matched rho on any family</small></div></div></div>
  <div class="panel"><h2>Distance remaining to the matched rho, by subgroup size</h2><p class="muted small">One panel per family because each family has its own unit and rho reference; ratios compare within a panel, never across. Filled dots: validated rows; hollow: unvalidated (pre-gate). Lower is closer; the dashed line is parity.</p>
    <div class="grid g3">${fams.map(([k, f]) => { const rs = d.rows.filter(r => r.family === k); return rs.length ? `<div><h3>${esc(k)}. ${esc(f.title)}</h3><p class="muted small" style="margin:0">unit: ${esc(f.unit_short)} · reference: ${esc(f.ref_short)}</p>${familyChart(f, rs)}</div>` : ""; }).join("")}</div>
    <p class="legend">${Object.entries(REGIME_LABEL).map(([k, l]) => `<span><i style="background:${REGIME_COLOR[k]}"></i>${esc(l)}</span>`).join("")}</p></div>
  <div class="panel"><h2>Current leaders</h2><table><tr><th>Family</th><th>Row</th><th>r</th><th>Recipe</th><th>× matched rho</th><th>Largest row</th></tr>${leaders.map(([k, l]) => `<tr><td>${esc(REGIME_LABEL[k] || k)}</td><td><code>${esc(l.slug)}</code></td><td>2^${fmt(l.log2_r)}</td><td>${esc(l.recipe)}</td><td><b>${fmt(l.ratio_rho)}×</b></td><td class="muted"><code>${esc(l.largest?.slug)}</code> 2^${fmt(l.largest?.log2_r)} at ${fmt(l.largest?.ratio_rho)}×</td></tr>`).join("")}</table></div>
  <div class="panel"><h2>Every board row</h2><table><tr><th>Family</th><th>Regime</th><th>Row</th><th>r</th><th>Best recipe</th><th>× matched rho</th><th>× floor</th><th>Verified / reps</th><th>Validation gate</th></tr>${d.rows.map(r => `<tr><td>${esc(r.family)}</td><td>${esc(REGIME_LABEL[r.regime] || r.regime)}</td><td><code class="small">${esc(r.slug)}</code></td><td>2^${r.log2_r.toFixed(1)}</td><td class="small">${esc(r.best_recipe)}</td><td><b>${r.ratio_rho.toFixed(2)}×</b></td><td>${r.ratio_floor ? r.ratio_floor.toFixed(1) + "×" : "—"}</td><td>${r.verified ? '<span class="ok">yes</span>' : "—"} / ${fmt(r.repetitions)}</td><td>${badge(r.validation_status === "validated" ? "validated" : "unvalidated")} <span class="muted small">${esc(r.validation_verdict || "")}${(r.validation_caveats || []).length ? "; caveats: " + esc(r.validation_caveats.join(", ")) : ""}</span></td></tr>`).join("")}</table></div>
  ${d.progress ? `<div class="panel"><h2>Research timeline: ${esc(d.progress.label || "")}</h2><table><tr><th>Date</th><th>Entry</th><th>Value</th><th>Class</th><th>Reference</th></tr>${d.progress.points.slice().reverse().map(p => `<tr><td class="muted">${esc(p.date)}</td><td>${esc(p.label)}<details><summary>detail</summary><p class="small">${esc(p.detail)}</p></details></td><td>${fmt(p.value)}</td><td>${badge(p.class)}</td><td class="${p.reference === "matched" ? "" : "warn"}">${esc(p.reference)} rho</td></tr>`).join("")}</table></div>` : ""}
  <div class="panel"><h2>Family definitions</h2><dl class="kv">${fams.map(([k, f]) => `<dt>${esc(k)}. ${esc(f.title)}</dt><dd><b>Unit:</b> ${esc(f.unit)}<br><b>Reference:</b> ${esc(f.reference)}<br><b>Floor:</b> ${esc(f.floor)}</dd>`).join("")}</dl></div>`;
}

// ---- findings & recommendations
route(/^\/p\/([^/]+)\/findings$/, async (pid, q) => {
  projNav(pid, "/findings");
  const tab = q.tab || "findings";
  const [findings, recs] = await Promise.all([api(`/api/projects/${pid}/findings`), api(`/api/projects/${pid}/recommendations`)]);
  const body = tab === "findings" ? `<div class="panel"><table><tr><th>Finding</th><th>Kind</th><th>Reproduction</th><th>Status</th><th>Evidence</th></tr>${findings.map(f => `<tr class="clickable" tabindex="0" ${on("click", () => location.hash = `#/p/${pid}/findings/${f.id}`)}><td><b>${esc(f.title)}</b> ${demo(f.is_demo)}<br><span class="muted small">${esc((f.summary || "").slice(0, 160))}</span></td><td>${esc(f.kind.replace(/_/g, " "))}</td><td>${badge(f.reproduction_status)}</td><td>${badge(f.status)}</td><td class="num">${(f.evidence_run_ids || []).length} runs</td></tr>`).join("") || '<tr><td colspan=5 class="muted">No findings.</td></tr>'}</table>
  <p class="small muted">Lifecycle: open → recommendation proposed → external change reported → awaiting retest → resolved within tested scope | still failing | inconclusive. A reported fix never closes a finding without a valid retest.</p></div>`
  : `<div class="panel"><table><tr><th>Recommendation</th><th>Category</th><th>Guidance kind</th><th>Review status</th><th>Implemented by</th></tr>${recs.map(r => `<tr class="clickable" tabindex="0" ${on("click", () => location.hash = `#/p/${pid}/recommendations/${r.id}`)}><td><b>${esc(r.title)}</b></td><td>${esc(r.category.replace(/_/g, " "))}</td><td>${badge(r.guidance_kind)}</td><td>${badge(r.status)}</td><td>${r.resulting_implementation_id ? "revised version imported" : (r.status === "approved" ? '<span class="warn small">awaiting external implementation</span>' : "—")}</td></tr>`).join("") || '<tr><td colspan=5 class="muted">No recommendations.</td></tr>'}</table>
  <p class="small muted">best practice = general guidance · hypothesis = needs testing · project-specific = supported by this project's results. Customers implement changes outside the platform.</p></div>
  <div class="panel"><h2>Engineering handoff</h2><p class="small">Findings, recommendations, evidence references and the retest plan. ${dlBtn(`/api/projects/${pid}/export/handoff?format=html`, "engineering_handoff.html", "Download HTML")} ${dlBtn(`/api/projects/${pid}/export/handoff`, "engineering_handoff.json", "Download JSON")}</p></div>`;
  return `<h1>Findings &amp; Recommendations</h1>${tabs(`#/p/${pid}/findings`, tab, [["findings", "Findings"], ["recommendations", "Recommendations"]])}${body}`;
});
route(/^\/p\/([^/]+)\/findings\/([^/]+)$/, async (pid, fid) => {
  projNav(pid, "/findings");
  const [f, impls, runs] = await Promise.all([api(`/api/projects/${pid}/findings/${fid}`), api(`/api/projects/${pid}/implementations`), api(`/api/projects/${pid}/runs`)]);
  const idx = f.lifecycle.indexOf(f.status);
  const revisedRuns = runs.filter(r => r.status === "completed" && f.revised_implementation && r.implementation_id === f.revised_implementation.id);
  return `<h1>${esc(f.title)} ${demo(f.is_demo)}</h1><p class="sub">${esc(f.kind.replace(/_/g, " "))} · origin ${esc(f.origin)} · ${badge(f.reproduction_status)} · ${when(f.created_at)}</p>
  <div class="flow">${f.lifecycle.filter(s => !["still_failing", "inconclusive", "not_relevant"].includes(s) || s === f.status).map((s, i) => `<span class="${s === f.status ? "cur" : (i < idx && idx >= 0 ? "done" : "")}">${esc(s.replace(/_/g, " "))}</span>`).join("")}</div>
  <div class="grid g2" style="margin-top:12px"><div><div class="panel"><h2>Finding</h2><p>${esc(f.summary)}</p>${f.failing_scenarios.length ? `<p><b>Failing scenarios:</b> <code>${esc(f.failing_scenarios.join(", "))}</code></p>` : ""}${f.failing_requirements.length ? `<p><b>Failing requirements:</b> ${esc(f.failing_requirements.join(", "))}</p>` : ""}
  <h3>Claims</h3>${f.claims.length ? `<table>${f.claims.map(c => `<tr><td>${esc(c.text)}</td><td>${badge(c.reproduced)}</td></tr>`).join("")}</table>` : '<p class="muted">none</p>'}<h3>Affected</h3><code class="small">${esc(JSON.stringify(f.affected))}</code><p>${f.affected_implementations.map(i => `<a href="#/p/${pid}/implementations/${i.id}">${esc(i.name)} ${esc(i.version)}</a> ${badge(i.status)}`).join(", ") || '<span class="muted">no implementation linked</span>'}</p><h3>Relevance</h3><p>${esc(f.relevance)}</p><h3>Uncertainty</h3><p>${esc(f.uncertainty)}</p>
  ${f.source ? `<h3>Source</h3><p>${esc(f.source.title)} ${demo(f.source.is_demo)} <code>sha256 ${esc(f.source.content_sha256.slice(0, 16))}…</code></p><details><summary>Show stored document (untrusted data)</summary><pre>${esc(f.source.content)}</pre></details>` : ""}</div>
  <div class="panel"><h2>Status history</h2><table>${f.status_history.map(h => `<tr><td>${badge(h.status)}</td><td class="small">${esc(h.note || "")}</td><td class="muted small">${h.at ? when(h.at) : ""}</td></tr>`).join("")}</table></div></div>
  <div><div class="panel elev"><h2>Loop</h2>
  <h3>1. Experiments</h3>${f.experiments.length ? `<ul class="tight">${f.experiments.map(p => `<li><a href="#/p/${pid}/experiments/${p.id}">${esc(p.title)}</a> ${badge(p.status)}${p.result_summary ? `<br><span class="small muted">${esc(p.result_summary)}</span>` : ""}</li>`).join("")}</ul>` : '<p class="muted small">none — use “Propose experiments” in Research &amp; Experiments</p>'}
  <h3>2. Recommendation</h3>${f.recommendation ? `<p><a href="#/p/${pid}/recommendations/${f.recommendation.id}">${esc(f.recommendation.title)}</a> ${badge(f.recommendation.guidance_kind)} ${badge(f.recommendation.status)}</p>` : `<button class="ghost sm" ${on("click", () => act(() => api(`/api/projects/${pid}/recommendations/from-finding/${fid}`, {method: "POST"}), "Recommendation drafted"))}>Generate recommendation</button>`}
  <h3>3. External change &amp; revised version</h3>${f.revised_implementation ? `<p>Revised: <a href="#/p/${pid}/implementations/${f.revised_implementation.id}">${esc(f.revised_implementation.name)} ${esc(f.revised_implementation.version)}</a>${f.revised_implementation.change_report ? `<br><span class="small muted">${esc(f.revised_implementation.change_report)}</span>` : ""}</p>` : `<form class="row" ${on("submit", (e) => act(() => api(`/api/projects/${pid}/findings/${fid}/report-change`, {method: "POST", body: {revised_implementation_id: e.target.impl.value, change_report: e.target.note.value}}), "Change reported; awaiting retest"))}><select name="impl" style="max-width:240px">${impls.filter(i => !(f.affected_implementation_ids || []).includes(i.id)).map(i => `<option value="${i.id}">${esc(i.name)} ${esc(i.version)}</option>`).join("")}</select><input name="note" placeholder="what changed externally" style="max-width:260px"><button class="ghost sm">Report change</button></form><p class="small muted">Import the corrected version first (Implementations), then link it here.</p>`}
  <h3>4. Retest</h3>${["awaiting_retest", "still_failing", "inconclusive", "external_change_reported"].includes(f.status) && f.revised_implementation ? `<div class="row"><select id="rtrun" style="max-width:300px">${revisedRuns.map(r => `<option value="${r.id}">#${r.sequence} ${esc(r.test_label)} [${esc(r.execution_mode)}] ${esc(r.classification)}</option>`).join("")}</select><button ${revisedRuns.length ? "" : "disabled"} ${on("click", () => act(() => api(`/api/projects/${pid}/findings/${fid}/retest`, {method: "POST", body: {run_id: $("#rtrun").value}}), "Retest evaluated"))}>Evaluate retest</button></div>${revisedRuns.length ? "" : '<p class="small muted">No completed run of the revised version yet — run it in Tests &amp; Benchmarks.</p>'}` : `<p class="small muted">${f.status === "resolved_within_tested_scope" ? "Resolved within the tested scope." : "Available once an external change is reported."}</p>`}
  ${["open", "recommendation_proposed"].includes(f.status) ? `<h3>Triage</h3><button class="danger sm" ${on("click", () => act(() => api(`/api/projects/${pid}/findings/${fid}/status`, {method: "POST", body: {status: "not_relevant", note: prompt("Why is this not relevant?") || ""}}), "Marked not relevant"))}>Mark not relevant (reviewer)</button>` : f.status === "not_relevant" ? `<button class="ghost sm" ${on("click", () => act(() => api(`/api/projects/${pid}/findings/${fid}/status`, {method: "POST", body: {status: "open"}}), "Reopened"))}>Reopen</button>` : ""}</div>
  <div class="panel"><h2>Evidence runs</h2><table>${f.evidence_runs.map(r => `<tr class="clickable" tabindex="0" ${on("click", () => location.hash = `#/p/${pid}/runs/${r.id}`)}><td>#${r.sequence}</td><td>${esc(r.execution_mode)}</td><td>${st(r.classification)}</td><td>${labels(r.evidence_labels)}</td></tr>`).join("") || '<tr><td class="muted">none</td></tr>'}</table></div></div></div>`;
});
route(/^\/p\/([^/]+)\/recommendations\/([^/]+)$/, async (pid, rid) => {
  projNav(pid, "/findings");
  const r = await api(`/api/projects/${pid}/recommendations/${rid}`);
  const b = r.body || {};
  return `<h1>${esc(r.title)}</h1><p class="sub">${esc(r.category.replace(/_/g, " "))} · ${badge(r.guidance_kind)} · review status ${badge(r.status)} · generated by ${esc(r.generated_by)}</p>
  <div class="grid g2"><div class="panel"><h3>Observed issue</h3><p>${esc(b.observed_issue)}</p><h3>Supporting evidence</h3>${(b.supporting_evidence || []).length ? `<table>${b.supporting_evidence.map(e => e.run_id ? `<tr><td><a href="#/p/${pid}/runs/${e.run_id}">run #${e.sequence}</a></td><td>${esc(e.execution_mode)}</td><td>${st(e.classification)}</td><td class="small bad">${esc((e.failing_scenarios || []).join(", "))}</td></tr>` : `<tr><td><a href="#/p/${pid}/experiments/${e.experiment_id}">${esc(e.title)}</a></td><td colspan=3 class="small">${esc(e.result)}</td></tr>`).join("")}</table>` : '<p class="muted">none linked</p>'}
  <h3>Proposed practice / implementation change</h3><p>${esc(b.proposed_change)}</p><h3>Relevant authoritative guidance</h3>${nl(b.authoritative_guidance)}<h3>Expected benefit</h3><p>${esc(b.expected_benefit)}</p><h3>Trade-offs</h3>${nl(b.tradeoffs)}<h3>Applicability limits</h3>${nl(b.applicability_limits)}<h3>Required retest</h3>${nl(b.required_retest)}<div class="callout">${esc(b.status_note || "A reported fix does not close the finding; the revised version must pass the required retest.")}</div></div>
  <div><div class="panel"><h2>Human review</h2><p class="small muted">Reviewer role; the author cannot approve their own recommendation. Approval unlocks linking a revised implementation import; nothing is deployed.</p><label>Note</label><input id="recnote"><p class="row"><button class="ghost" ${on("click", () => act(() => api(`/api/projects/${pid}/recommendations/${rid}/decide`, {method: "POST", body: {decision: "reviewed", note: $("#recnote").value}}), "Marked reviewed"))}>Mark reviewed</button><button ${on("click", () => act(() => api(`/api/projects/${pid}/recommendations/${rid}/decide`, {method: "POST", body: {decision: "approved", note: $("#recnote").value}}), "Approved"))}>Approve</button><button class="ghost" ${on("click", () => act(() => api(`/api/projects/${pid}/recommendations/${rid}/decide`, {method: "POST", body: {decision: "needs_changes", note: $("#recnote").value}}), "Needs changes"))}>Needs changes</button><button class="danger" ${on("click", () => act(() => api(`/api/projects/${pid}/recommendations/${rid}/decide`, {method: "POST", body: {decision: "rejected", note: $("#recnote").value}}), "Rejected"))}>Reject</button></p>
  <table>${r.approvals.map(a => `<tr><td>${badge(a.decision)}</td><td>${esc(a.note)}</td><td class="muted small">${when(a.created_at)}</td></tr>`).join("") || '<tr><td class="muted">no decisions yet</td></tr>'}</table></div>
  <div class="panel"><h2>Links</h2><dl class="kv"><dt>Finding</dt><dd>${r.finding ? `<a href="#/p/${pid}/findings/${r.finding.id}">${esc(r.finding.title)}</a> ${badge(r.finding.status)}` : "—"}</dd><dt>Target implementation</dt><dd>${r.target_implementation ? `<a href="#/p/${pid}/implementations/${r.target_implementation.id}">${esc(r.target_implementation.name)} ${esc(r.target_implementation.version)}</a>` : "—"}</dd><dt>Revised implementation</dt><dd>${r.resulting_implementation ? `<a href="#/p/${pid}/implementations/${r.resulting_implementation.id}">${esc(r.resulting_implementation.name)} ${esc(r.resulting_implementation.version)}</a> ${badge(r.resulting_implementation.status)}` : (r.status === "approved" ? '<span class="warn">awaiting external implementation — import the revised version and select this recommendation</span>' : "—")}</dd></dl></div></div></div>`;
});

