route(/^\/p\/([^/]+)\/evidence$/, async (pid, q) => {
  projNav(pid, "/evidence");
  const tab = q.tab || "bundles";
  const [bundles, keys, pk, runners, artifacts] = await Promise.all([api(`/api/projects/${pid}/bundles`), api(`/api/projects/${pid}/trusted-keys`), api("/api/platform-key"), api("/api/runners"), api(`/api/projects/${pid}/artifacts`)]);
  let body = "";
  if (tab === "bundles") body = `<div class="panel"><table><tr><th>Run</th><th>Kind</th><th>Signer</th><th>Envelope SHA-256</th><th>Classification</th><th>Labels</th><th>Countersigned</th><th>When</th></tr>${bundles.slice().reverse().map(b => `<tr class="clickable" tabindex="0" ${on("click", () => location.hash = `#/p/${pid}/bundles/${b.id}`)}><td>#${b.run_sequence}</td><td>${esc(b.kind)}</td><td>${esc(b.signer_name || "")}</td><td class="mono">${esc(b.envelope_sha256.slice(0, 16))}…</td><td>${st(b.classification)}</td><td>${labels(b.labels)}</td><td>${b.countersignature ? '<span class="small">ingestion receipt</span>' : "—"}</td><td class="muted small">${when(b.created_at)}</td></tr>`).join("") || '<tr><td colspan=8 class="muted">No bundles yet.</td></tr>'}</table>
  <p class="small muted">Labels are separate and composable: imported · hash-checked · signature-verified · Cairn-verified (never applied: no Cairn checker configured) · independently replayed. Human approval, test execution and independent checks remain distinct.</p></div>
  <div class="panel"><h2>Artifacts</h2><table>${artifacts.slice().reverse().map(a => `<tr><td>${esc(a.kind)}</td><td>${esc(a.filename)}</td><td class="num">${a.size} B</td><td class="mono">${esc(a.sha256.slice(0, 16))}…</td><td>${dlBtn(`/api/projects/${pid}/artifacts/${a.id}/download`, a.filename, "download")}</td></tr>`).join("")}</table></div>`;
  else if (tab === "keys") body = `<div class="grid g2"><div class="panel"><h2>Trust policy — accepted signers</h2><table><tr><th>Name</th><th>Purpose</th><th>Scope</th><th>Key id</th><th>Status</th><th></th></tr>${keys.map(k => `<tr><td>${esc(k.name)}</td><td>${esc(k.purpose)}</td><td>${esc(k.scope)}</td><td class="mono">${esc(k.key_id.slice(0, 16))}…</td><td>${badge(k.status)}</td><td>${k.scope === "project" && k.status === "active" ? `<button class="danger sm" ${on("click", () => act(() => api(`/api/projects/${pid}/trusted-keys/${k.id}/revoke`, {method: "POST"}), "Key revoked"))}>revoke</button>` : ""}</td></tr>`).join("")}</table>
  <h3>Register a customer-runner public key (owner)</h3><form ${on("submit", (e) => act(() => api(`/api/projects/${pid}/trusted-keys`, {method: "POST", body: {name: e.target.name.value, public_key_pem: e.target.pem.value, note: e.target.note.value}}), "Key registered"))}><label>Name</label><input name="name" required><label>PUBLIC key PEM (from runner_key.pem.pub — never the private key)</label><textarea name="pem" required></textarea><label>Note</label><input name="note"><p><button class="ghost sm">Register</button></p></form></div>
  <div class="panel"><h2>Platform signing key</h2><p class="small">Platform bundles are signed with this key. Copy the PEM into your verifier trust file; distribute out-of-band. Rotation and revocation: docs/ATTESTATION.md.</p><p class="mono small">key id ${esc(pk.key_id)}</p><pre>${esc(pk.public_key_pem)}</pre></div></div>`;
  else if (tab === "verify") body = `<div class="grid g2"><div class="panel"><h2>Standalone verifier</h2><p class="small">Works without a platform account; needs Python 3 and <code>cryptography</code>. Trust comes only from the keys you pass.</p><pre>python -m iel_tools.verify bundle.json \\
  --trusted-key platform.pub --trusted-key runner_key.pem.pub [--json]</pre><p class="small muted">Checks structure, signature + expected signer, artifact digests; reports missing artifacts, unsupported formats and failed checks, and what remains unverified (e.g. that the reported environment was genuine).</p></div>
  <div class="panel"><h2>Verify a bundle here (same checks)</h2><form ${on("submit", async (e) => { let bundle; try { bundle = await readJsonFile(e.target.bundle); } catch (err) { return toast(err.message, true); } const pems = e.target.pems.value.split(/(?=-----BEGIN)/).map(s => s.trim()).filter(Boolean); try { const r = await api("/api/verify-bundle", {method: "POST", body: {bundle, trusted_keys_pem: pems}}); $("#vresult").innerHTML = `<div class="callout ${r.ok ? "ok" : "bad"}"><b>${r.ok ? "ALL CHECKS PASSED" : "CHECKS FAILED"}</b>${nl(r.verified.map(x => "verified: " + x))}${nl(r.unverified.map(x => "unverified: " + x))}${nl(r.problems.map(x => "PROBLEM: " + x))}</div>`; } catch (err) { toast(err.message, true); } })}><label>Bundle file</label><input type="file" name="bundle" accept=".json"><label>Trusted public keys (PEM, one or more)</label><textarea name="pems">${esc(pk.public_key_pem)}</textarea><p><button class="ghost sm">Verify</button></p></form><div id="vresult"></div></div></div>`;
  else body = `<div class="grid g3"><div class="panel"><h2>Evidence package</h2><p class="small">Append-only records, original signed envelopes, artifacts and a SHA-256 manifest.</p>${dlBtn(`/api/projects/${pid}/export/package`, "evidence_package.zip", "Download zip", "ghost")}</div>
  <div class="panel"><h2>Engineering handoff</h2><p class="small">Findings, recommendations, evidence references, retest plan.</p>${dlBtn(`/api/projects/${pid}/export/handoff?format=html`, "engineering_handoff.html", "Download HTML", "ghost")} ${dlBtn(`/api/projects/${pid}/export/handoff`, "engineering_handoff.json", "JSON")}</div>
  <div class="panel"><h2>Compliance evidence template (optional)</h2><p class="small">Maps evidence to PCI DSS v4.0.1 Req. 12.3.3 and Regulation (EU) 2024/1774 Art. 6(4)-(5). Provisional mappings; statuses mapped / not mapped / not applicable / insufficient evidence; missing evidence is identified. Printable with the light logo.</p><form ${on("submit", async (e) => { const f = e.target; const app = {}; for (const c of ["PCI DSS v4.0.1 Requirement 12.3.3", "Commission Delegated Regulation (EU) 2024/1774, Article 6(4)-(5) (supplementing DORA)"]) app[c] = {confirmed: f[c].checked, scope: f.scope.value, owner: f.owner.value, next_review: f.next.value}; if (window.IEL_STATIC) return dl(`POST /api/projects/${pid}/export/compliance?format=html`, "compliance_evidence.html"); try { const r = await fetch(`/api/projects/${pid}/export/compliance`, {method: "POST", headers: {"Content-Type": "application/json", Authorization: "Bearer " + TOKEN}, body: JSON.stringify({applicability: app, format: "html"})}); const b = await r.blob(); const a = document.createElement("a"); a.href = URL.createObjectURL(b); a.download = "compliance_evidence.html"; a.click(); } catch (err) { toast(err.message, true); } })}><label><input type="checkbox" name="PCI DSS v4.0.1 Requirement 12.3.3"> PCI DSS 12.3.3 applies (customer-confirmed)</label><label><input type="checkbox" name="Commission Delegated Regulation (EU) 2024/1774, Article 6(4)-(5) (supplementing DORA)"> EU 2024/1774 Art. 6(4)-(5) applies (customer-confirmed)</label><div class="grid g3"><div><label>Scope</label><input name="scope"></div><div><label>Owner</label><input name="owner"></div><div><label>Next review</label><input name="next" placeholder="2027-01-31"></div></div><p><button class="ghost sm">Generate HTML</button></p></form><p class="small muted">This export supports compliance review. It is not a certification, legal opinion or determination that the organization meets the referenced requirements.</p></div></div>
  <div class="panel"><h2>Runners</h2><table><tr><th>Kind</th><th>Version</th><th>Available</th><th>Implemented</th><th>Tested here</th><th>Description</th></tr>${runners.map(r => `<tr><td><code>${esc(r.kind)}</code></td><td>${esc(r.version)}</td><td>${r.available ? '<span class="ok">yes</span>' : `<span class="bad">no</span> <span class="muted small">${esc(r.unavailable_reason)}</span>`}</td><td>${r.implemented ? "yes" : "interface only"}</td><td>${r.tested_in_this_environment ? "yes" : '<span class="warn">no</span>'}</td><td class="muted small">${esc(r.description)}</td></tr>`).join("")}</table></div>`;
  return `<h1>Evidence</h1>${tabs(`#/p/${pid}/evidence`, tab, [["bundles", "Signed bundles & artifacts"], ["keys", "Trusted keys"], ["verify", "Verifier"], ["exports", "Exports"]])}${body}`;
});
route(/^\/p\/([^/]+)\/bundles\/([^/]+)$/, async (pid, bid) => {
  projNav(pid, "/evidence");
  const b = await api(`/api/projects/${pid}/bundles/${bid}`);
  const lv = b.live_verification, pred = b.statement.predicate || {};
  return `<h1>${esc(b.kind)} evidence bundle — run #${b.run.sequence}</h1><p class="sub">${esc(b.format)} · signer ${esc(b.signer_name || "")} <code>${esc((b.signer_keyid || "").slice(0, 16))}…</code> · envelope sha256 <code>${esc(b.envelope_sha256.slice(0, 20))}…</code> · <a href="#/p/${pid}/runs/${b.run.id}">run record</a></p>
  <div class="grid g2"><div><div class="panel"><h2>Verification (live, against the current trust policy)</h2><div class="callout ${lv.ok ? "ok" : "bad"}"><b>${lv.ok ? "ALL CHECKS PASSED" : "CHECKS FAILED"}</b> — signer ${esc(lv.signer || "untrusted")}</div>${nl(lv.verified.map(x => "verified: " + x))}${nl(lv.unverified.map(x => "unverified: " + x))}${lv.problems.length ? `<div class="callout bad">${nl(lv.problems)}</div>` : ""}<p>Labels: ${labels(b.labels)}</p><p class="small muted">Cairn: ${esc(b.cairn.note)}</p>${b.verification.duplicate_of ? `<div class="callout">Duplicate of run <a href="#/p/${pid}/runs/${b.verification.duplicate_of}">${esc(b.verification.duplicate_of.slice(0, 8))}</a></div>` : ""}${(b.verification.stale || []).length ? `<div class="callout">Stale: ${esc(b.verification.stale.join("; "))}</div>` : ""}</div>
  ${b.countersignature ? `<div class="panel"><h2>Platform ingestion receipt (countersignature)</h2><p class="small muted">The platform countersigned the digest of the customer envelope as a receipt. This is NOT an independent endorsement of the contents; the original envelope is preserved unchanged.</p><pre>${esc(JSON.stringify(b.countersignature, null, 1).slice(0, 1500))}</pre></div>` : ""}</div>
  <div><div class="panel"><h2>Statement</h2><dl class="kv"><dt>Subjects</dt><dd>${nl(b.statement.subject.map(s => `${s.name} — sha256 ${s.digest.sha256.slice(0, 16)}…`))}</dd><dt>Predicate type</dt><dd><code>${esc(b.statement.predicateType)}</code></dd><dt>Binding</dt><dd>project ${esc(pred.project_id)} · run ${esc(pred.run_id)} · ${esc(pred.implementation?.name)} ${esc(pred.implementation?.version)} · test ${esc(pred.test?.test_id)}@${esc(pred.test?.version)} · mode ${esc(pred.execution_mode)}</dd><dt>Executed at (reported)</dt><dd>${esc(pred.executed_at || "—")}</dd><dt>Classification (reported)</dt><dd>${st(pred.results?.classification)}</dd></dl>${b.bundle_artifact ? dlBtn(`/api/projects/${pid}/artifacts/${b.bundle_artifact.id}/download`, b.bundle_artifact.filename, "Download bundle file") : ""}<details style="margin-top:8px"><summary>Full statement</summary>${json(b.statement)}</details><details><summary>DSSE envelope (original)</summary>${json(b.envelope)}</details></div></div></div>`;
});

// ---- audit & system
route(/^\/p\/([^/]+)\/audit$/, async (pid) => {
  projNav(pid, "/evidence");
  const ev = await api(`/api/projects/${pid}/audit`);
  return `<h1>Audit history</h1><div class="panel"><table><tr><th>When</th><th>Actor</th><th>Action</th><th>Subject</th><th>Detail</th></tr>${ev.map(e => `<tr><td class="muted small">${when(e.created_at)}</td><td>${esc(e.actor || "system")}</td><td><code>${esc(e.action)}</code></td><td>${esc(e.subject_type)}</td><td><code class="small">${esc(JSON.stringify(e.detail))}</code></td></tr>`).join("")}</table></div>`;
});
route(/^\/system$/, async () => {
  $("#projnav").innerHTML = "";
  const [runners, cat, jobs, pk] = await Promise.all([api("/api/runners"), api("/api/catalog"), api("/api/jobs"), api("/api/platform-key")]);
  return `<h1>System</h1><p class="sub">What is implemented and tested here versus interface-only. No claim of production readiness or tenant isolation.</p>
  <div class="panel"><h2>Runners</h2><table><tr><th>Kind</th><th>Version</th><th>Provenance</th><th>Fixtures</th><th>Available</th><th>Implemented</th><th>Tested here</th><th>Description</th></tr>${runners.map(r => `<tr><td><code>${esc(r.kind)}</code></td><td>${esc(r.version)}</td><td>${prov(r.provenance)}</td><td class="small"><code>${esc((r.fixtures || ["*"]).join(", "))}</code></td><td>${r.available ? '<span class="ok">yes</span>' : `<span class="bad">no</span> <span class="muted small">${esc(r.unavailable_reason)}</span>`}</td><td>${r.implemented ? "yes" : "interface only"}</td><td>${r.tested_in_this_environment ? "yes" : '<span class="warn">no</span>'}</td><td class="muted small">${esc(r.description)}</td></tr>`).join("")}</table></div>
  <div class="panel"><h2>Platform signing key</h2><p class="mono small">key id ${esc(pk.key_id)}</p><pre>${esc(pk.public_key_pem)}</pre></div>
  <div class="panel"><h2>Catalog (${esc(cat.catalog_date)})</h2><table><tr><th>Profile</th><th>Purpose</th><th>Standards</th><th>Sizes</th><th>Fixture</th></tr>${cat.profiles.map(p => `<tr><td><b>${esc(p.label)}</b> <code>${esc(p.id)}</code></td><td>${esc(p.purpose)}</td><td class="small">${esc(p.standards.join("; "))}</td><td><code class="small">${esc(JSON.stringify(p.sizes))}</code></td><td>${p.fixture ? `<code>${esc(p.fixture)}</code>` : '<span class="muted">none</span>'}</td></tr>`).join("")}</table></div>
  <div class="panel"><h2>Background jobs</h2><table><tr><th>Kind</th><th>Status</th><th>Error</th><th>When</th></tr>${jobs.map(j => `<tr><td>${esc(j.kind)}</td><td>${badge(j.status)}</td><td class="bad small">${esc((j.error || "").slice(0, 160))}</td><td class="muted small">${when(j.created_at)}</td></tr>`).join("") || '<tr><td class="muted">none</td></tr>'}</table></div>`;
});
render();
